do $$
begin
  if exists (
    with incoming (id, subtopic_id, stable_code, bank_kind, prompt, explanation, sort_order, options) as (
      values
  ('e8ec9ba1-fb17-118c-9b73-dfbabc79a90d', '534e4d64-402f-3719-316a-6da910b558fa', 'QB1101', 'section', '下列何者為自然色彩？', '本單元探討色彩的來源，核心觀念在於光色原理與可見光譜。英國科學家牛頓於1666年利用三棱鏡將太陽光（白光／複色光）分解為紅、橙、黃、綠、藍、靛、紫等七色光譜，揭開了光與色彩的關係。人類眼睛能感知的範圍稱為可見光譜（波長約380nm至780nm），而無法再經由三棱鏡分解的單一色光則稱為單色光。', 1, '[{"is_correct":false,"key":"A","sort_order":1,"text":"染色布"},{"is_correct":false,"key":"B","sort_order":2,"text":"手錶"},{"is_correct":true,"key":"C","sort_order":3,"text":"公園的花草"},{"is_correct":false,"key":"D","sort_order":4,"text":"藍色襯衫"}]'::jsonb),
  ('561a148d-1929-97b2-2251-d0fa701a8811', '171b4ec0-88cf-0b02-ff94-fd08893e802d', 'QB1201', 'section', '下列生物何者不具有色覺？', '本單元探討色彩與生活，核心觀念在於生活中色彩的感知與應用。色彩廣泛存在於我們的日常環境中，不僅能引發心理上的冷暖、輕重、前進與後退等感覺，更在品牌設計、視覺傳達與生活美感教育中扮演重要角色。透過對生活中色彩的察覺與分析，能提升對美感的認知與色彩配置的能力。', 1, '[{"is_correct":true,"key":"A","sort_order":1,"text":"牛"},{"is_correct":false,"key":"B","sort_order":2,"text":"猴子"},{"is_correct":false,"key":"C","sort_order":3,"text":"孔雀"},{"is_correct":false,"key":"D","sort_order":4,"text":"鸚鵡"}]'::jsonb),
  ('4c628381-f70b-ddca-e85b-e85a9e235831', '5e9f788b-0071-ca7c-7c25-8d50ab0822f2', 'QB1301', 'section', '在法國拉斯考洞穴壁面上，一萬多年前的人類以色彩描繪馬、牛、豬、鹿及狩獵圖畫，其中所用的色彩何者為非？', '本單元探討色彩的發展歷程，核心觀念在於人類對色彩認知與應用的歷史演變。從遠古時期原始人利用礦石、草木等自然素材塗繪洞窟壁畫，到古埃及時代將色料廣泛應用於墓穴畫。隨後歷經科學革命與近代發展，科學家與藝術家逐漸建立系統化的色彩理論與表色模型，為現代色彩學與數位色彩模式奠定了科學與藝術融合的基礎。', 1, '[{"is_correct":false,"key":"A","sort_order":1,"text":"黑"},{"is_correct":false,"key":"B","sort_order":2,"text":"白"},{"is_correct":false,"key":"C","sort_order":3,"text":"紅"},{"is_correct":true,"key":"D","sort_order":4,"text":"藍"}]'::jsonb),
  ('c0311097-ca0a-f5e0-1d33-ee0f1eb3055a', '7ca4dc67-1bcd-7021-1aaa-97c7d9f599a7', 'QB2101', 'section', '西元1666年以三稜鏡分解太陽光分析出光譜的學者是？', '本單元探討色彩呈現，核心觀念在於色彩與光的關係。光是視覺現象的主要媒體，也是感知色彩的刺激物，沒有光就無法產生視覺。物體本身並沒有固定的色彩，其呈現的色彩會隨著光源條件而改變，當光線照射到物體上時，一部分光線被物體吸收，另一部分則被反射或透射，進而刺激人類眼睛並由大腦解讀，產生對色彩的感知。', 1, '[{"is_correct":false,"key":"A","sort_order":1,"text":"達文西"},{"is_correct":false,"key":"B","sort_order":2,"text":"愛迪生"},{"is_correct":true,"key":"C","sort_order":3,"text":"牛頓"},{"is_correct":false,"key":"D","sort_order":4,"text":"達爾文"}]'::jsonb),
  ('bcb87a3e-0c45-85aa-9249-d82ad940241d', '6cd3f97b-df9a-a718-2e60-d46dad98856d', 'QB2201', 'section', '色光三原色是：', '本單元探討色光的原色與混色，核心觀念在於加法混色（加色混合、正混合）原理。色光三原色為紅（Red）、綠（Green）、藍（Blue），因其無法再被分解，也不能由其他色光混合而成。當不同比例的色光重疊混合時，其能量與明度會相加提升，兩兩等量混合可產生第二次色（紅+綠=黃、紅+藍=洋紅、藍+綠=青），而三原色等量混合則會組合成白光。', 1, '[{"is_correct":false,"key":"A","sort_order":1,"text":"紅、黃、藍"},{"is_correct":false,"key":"B","sort_order":2,"text":"黃、綠、紅"},{"is_correct":true,"key":"C","sort_order":3,"text":"紅、藍、綠"},{"is_correct":false,"key":"D","sort_order":4,"text":"白、紅、青"}]'::jsonb),
  ('f7bf2f97-cfc7-a3d8-6592-f10845f83a39', 'a6644b36-ebdf-7f9e-5658-0cd923c817dc', 'QB2301', 'section', '色料三原色是指：', '本單元探討色料的原色與混合，核心觀念在於減法混色原理與色料三原色。色料三原色為青（Cyan）、洋紅（Magenta）、黃（Yellow），簡稱CMY，其特性為無法透過其他顏色混合而成。當不同的色料相混合時，由於色料會吸收光線，混合後的色彩明度與彩度會降低，且混合的顏色愈多，色彩愈顯暗濁，最終趨近於黑色，此現象稱為「減法混合」。在印刷或噴墨列印等實際應用中，通常會加入黑色（Black）以補足無法混出純黑的限制，形成CMYK四色印刷模式。', 1, '[{"is_correct":false,"key":"A","sort_order":1,"text":"洋紅、黃、綠"},{"is_correct":false,"key":"B","sort_order":2,"text":"洋紅、綠、藍"},{"is_correct":false,"key":"C","sort_order":3,"text":"綠、藍、紫"},{"is_correct":true,"key":"D","sort_order":4,"text":"洋紅、黃、青"}]'::jsonb),
  ('f3d3be90-9a33-9596-067c-6c0c535340ba', '155d9baa-d963-36d1-ec22-a6d96c34c5bb', 'QB2401', 'section', '某一畫面是由無數個色塊拼湊而成的混色效果，此種色彩混合類型稱為？', '本單元探討中間混合（又稱中性混合或平均混合），核心觀念在於其混色後的明度為原色彩的面積加權平均值。中間混合屬於生理性混色，主要分為「旋轉混色」（如旋轉的色標）與「並置混色」（如彩色印刷網點、織物經緯線、螢幕像素）。當不同色彩的細小點或線密集排列，或快速交替時，會超越人類眼睛的空間或時間解析度，因而在大腦中生理性地融合成新的中間色。', 1, '[{"is_correct":false,"key":"A","sort_order":1,"text":"減色混合"},{"is_correct":false,"key":"B","sort_order":2,"text":"加色混合"},{"is_correct":true,"key":"C","sort_order":3,"text":"並置混合"},{"is_correct":false,"key":"D","sort_order":4,"text":"同時加法混合"}]'::jsonb),
  ('bb1d452c-3ccd-ec91-ed29-45224e709e91', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3101', 'section', '純色加入黑色所得的色彩稱為？', '正確答案為（D）暗色。純色加入黑色後，會使其明度與彩度同時降低，形成暗色。其他選項解析：（A）明色是指純色加入白色，會提高明度；（B）中間色與（C）濁色通常是指純色加入灰色，會使色彩變得混濁。', 1, '[{"is_correct":false,"key":"A","sort_order":1,"text":"明色"},{"is_correct":false,"key":"B","sort_order":2,"text":"中間色"},{"is_correct":false,"key":"C","sort_order":3,"text":"濁色"},{"is_correct":true,"key":"D","sort_order":4,"text":"暗色"}]'::jsonb),
  ('3a21e5a4-d0ef-1e5f-6aab-334a44f0b0c6', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3102', 'section', '明色和暗色因為不含灰色，所以又稱為？', '正確答案為（A）清色。清色是指純色僅加入白色（明色）或黑色（暗色），不含灰色成分。其他選項解析：（B）純色是指未經混合的飽和色彩；（C）濁色是指純色中加入了灰色；（D）補色是指色相環上相對立的兩種顏色。', 2, '[{"is_correct":true,"key":"A","sort_order":1,"text":"清色"},{"is_correct":false,"key":"B","sort_order":2,"text":"純色"},{"is_correct":false,"key":"C","sort_order":3,"text":"濁色"},{"is_correct":false,"key":"D","sort_order":4,"text":"補色"}]'::jsonb),
  ('4cb7062e-f03d-d664-fa98-73de921b46fa', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3103', 'section', '在一個純色中，同時加入白色與黑色，就會成為：', '正確答案為（D）濁色。同時加入白色與黑色等同於加入灰色，純色加入灰色後會降低彩度，形成濁色。其他選項解析：（A）明色是純色僅加入白色；（B）混色並非此情況的專有名稱；（C）白色為無彩色，加入純色並不會變成純白色。', 3, '[{"is_correct":false,"key":"A","sort_order":1,"text":"明色"},{"is_correct":false,"key":"B","sort_order":2,"text":"混色"},{"is_correct":false,"key":"C","sort_order":3,"text":"白色"},{"is_correct":true,"key":"D","sort_order":4,"text":"濁色"}]'::jsonb),
  ('f2ce1bcb-f205-e903-2276-c6884ca78ffb', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3104', 'section', '金色、銀色在色彩的分類中屬於：', '正確答案為（C）獨立色。金色和銀色具有特殊的金屬光澤，無法透過一般顏料混合而成，因此獨立於一般有彩色之外，稱為獨立色。其他選項解析：（A）無彩色僅包含黑、白、灰；（B）原色為無法被調配出來的基本色（如紅黃藍）；（D）純色是指飽和度最高的有彩色。', 4, '[{"is_correct":false,"key":"A","sort_order":1,"text":"無彩色"},{"is_correct":false,"key":"B","sort_order":2,"text":"原色"},{"is_correct":true,"key":"C","sort_order":3,"text":"獨立色"},{"is_correct":false,"key":"D","sort_order":4,"text":"純色"}]'::jsonb),
  ('34aee41b-3cff-28f8-d6d7-7524a2b6bca0', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3105', 'section', '下列色彩何者不屬於特殊色？', '正確答案為（B）七彩色。七彩色是多種顏色的組合，並非單一的特殊色彩。其他選項解析：（A）銅色與（D）錫箔色具有金屬光澤，（C）螢光綠色具有發光效果，三者皆具有特殊的視覺效果，屬於特殊色。', 5, '[{"is_correct":false,"key":"A","sort_order":1,"text":"銅色"},{"is_correct":true,"key":"B","sort_order":2,"text":"七彩色"},{"is_correct":false,"key":"C","sort_order":3,"text":"螢光綠色"},{"is_correct":false,"key":"D","sort_order":4,"text":"錫箔色"}]'::jsonb),
  ('47302ab0-1a34-ab09-bb2f-96709d17a5d4', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3106', 'section', '色彩的三屬性是：', '正確答案為（A）色相、明度、彩度。這是色彩學中最基本的分類方式。其他選項解析：（B）光線、物體、眼睛是構成視覺的三要素，而非色彩屬性；（C）與（D）波長、震幅等屬於物理光學的範疇，雖然與色彩有關，但並非色彩的三屬性。', 6, '[{"is_correct":true,"key":"A","sort_order":1,"text":"色相、明度、彩度"},{"is_correct":false,"key":"B","sort_order":2,"text":"光線、物體、眼睛"},{"is_correct":false,"key":"C","sort_order":3,"text":"波長、震幅、密度"},{"is_correct":false,"key":"D","sort_order":4,"text":"波長、對比、濃淡"}]'::jsonb),
  ('be222652-5a67-f9c2-932d-04f8299f7cef', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3107', 'section', '下列有關色相（Hue）的描述，何者不正確？', '正確答案為（C）。光線反射的強弱決定的是色彩的「明度」（亮度），而非「色相」。其他選項解析：（A）與（B）皆正確描述了色相是用來區分不同顏色的名稱與樣貌；（D）正確，不同波長的光會讓我們感受到不同的色相。', 7, '[{"is_correct":false,"key":"A","sort_order":1,"text":"指辨識色彩的相貌，區別各種不同色彩的名稱"},{"is_correct":false,"key":"B","sort_order":2,"text":"色彩區分為紅、黃、藍等不同的樣貌"},{"is_correct":true,"key":"C","sort_order":3,"text":"以光線反射的強弱分出其間的感覺差異"},{"is_correct":false,"key":"D","sort_order":4,"text":"光的波長決定其色相"}]'::jsonb),
  ('cb3f01af-9814-4242-3952-6d30f4327f6a', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3108', 'section', '關於「明度」的定義，下列何者錯誤？', '正確答案為（D）。色光的波長決定的是「色相」，而非「明度」。其他選項解析：（A）明度就是指色彩的明暗程度；（B）在物理學上，光波的振幅大小決定了光的強弱，即明度；（C）物體表面對光線的反射率越高，看起來就越亮，即明度越高。', 8, '[{"is_correct":false,"key":"A","sort_order":1,"text":"色彩的明暗"},{"is_correct":false,"key":"B","sort_order":2,"text":"色光的振幅"},{"is_correct":false,"key":"C","sort_order":3,"text":"色光的反射率"},{"is_correct":true,"key":"D","sort_order":4,"text":"色光的波長"}]'::jsonb),
  ('12d7f293-d314-f4ff-bb5a-9f4ca56ca31e', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3109', 'section', '中國水墨畫的「墨分五色」是利用色彩何種屬性的變化？', '正確答案為（A）明度。水墨畫中的「墨分五色」（焦、濃、重、淡、清）是藉由控制水分的多寡，來改變墨色的濃淡與明暗層次，這正是色彩「明度」的變化。其他選項解析：水墨畫主要使用黑色，無（B）彩度變化；（C）質感與（D）形態則與色彩屬性無直接關係。', 9, '[{"is_correct":true,"key":"A","sort_order":1,"text":"明度"},{"is_correct":false,"key":"B","sort_order":2,"text":"彩度"},{"is_correct":false,"key":"C","sort_order":3,"text":"質感"},{"is_correct":false,"key":"D","sort_order":4,"text":"形態"}]'::jsonb),
  ('3dca3b26-08da-c1df-8766-a466de70c92f', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3110', 'section', '下列純色何者明度最高？', '正確答案為（A）黃色。在所有有彩色的純色中，黃色的光反射率最高，因此明度最高。其他選項解析：（B）紅色明度居中；（C）紫色的光反射率最低，是純色中明度最低的；（D）黑色為無彩色，且明度最低。', 10, '[{"is_correct":true,"key":"A","sort_order":1,"text":"黃色"},{"is_correct":false,"key":"B","sort_order":2,"text":"紅色"},{"is_correct":false,"key":"C","sort_order":3,"text":"紫色"},{"is_correct":false,"key":"D","sort_order":4,"text":"黑色"}]'::jsonb),
  ('4bd7b732-4921-46b9-61df-0c256760b23a', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3111', 'section', '依照曼塞爾（Munsell）表色系的明度階段，白、亮灰、淺灰的明度調子接近：', '白、亮灰、淺灰屬於高明度，接近N10、N9、N8。N0至N2為低明度，N3至N6為中明度。故選項D正確。', 11, '[{"is_correct":false,"key":"A","sort_order":1,"text":"N0、N1、N2"},{"is_correct":false,"key":"B","sort_order":2,"text":"N2、N3、N4"},{"is_correct":false,"key":"C","sort_order":3,"text":"N4、N5、N6"},{"is_correct":true,"key":"D","sort_order":4,"text":"N10、N9、N8"}]'::jsonb),
  ('bcfb6527-04bb-8c3d-b8c2-5aa6bf7092c6', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3112', 'section', '曼塞爾（Munsell）表色系將明度由黑至白分為9個階段，所謂「低調子」指的是？', '低調子指的是低明度階段，即N1、N2、N3。N7以上為高調子，N4至N6為中調子。故選項B正確。', 12, '[{"is_correct":false,"key":"A","sort_order":1,"text":"N0、N5、N10"},{"is_correct":true,"key":"B","sort_order":2,"text":"N1、N2、N3"},{"is_correct":false,"key":"C","sort_order":3,"text":"N4、N5、N6"},{"is_correct":false,"key":"D","sort_order":4,"text":"N7、N8、N9"}]'::jsonb),
  ('31bac193-5439-b568-1a96-a3f3707fc468', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3113', 'section', '下列哪一色與白色混合後，明度階段變化最小？', '黃色是純色中明度最高的色彩，與白色混合後明度變化最小。綠、紅、藍明度較低，加白後明度變化較大。故選項C正確。', 13, '[{"is_correct":false,"key":"A","sort_order":1,"text":"綠"},{"is_correct":false,"key":"B","sort_order":2,"text":"紅"},{"is_correct":true,"key":"C","sort_order":3,"text":"黃"},{"is_correct":false,"key":"D","sort_order":4,"text":"藍"}]'::jsonb),
  ('2bc6e3b6-105b-2a77-448b-eb29779bded4', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3114', 'section', '下列有關彩度之定義，何者不正確？', '彩度指的是色彩的純度、飽和度或鮮濁度。調和度並非彩度的定義。故選項B不正確。', 14, '[{"is_correct":false,"key":"A","sort_order":1,"text":"色彩的飽和度"},{"is_correct":true,"key":"B","sort_order":2,"text":"色彩的調和度"},{"is_correct":false,"key":"C","sort_order":3,"text":"色彩的鮮濁度"},{"is_correct":false,"key":"D","sort_order":4,"text":"色彩的純度"}]'::jsonb),
  ('fe9e3abe-779f-e8f0-4cf2-d5e22f21e22d', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3115', 'section', '在純色中，彩度最高的是：', '在所有純色中，黃色明度最高，但紅色在感官上最為鮮豔，彩度最高。故選項B正確。', 15, '[{"is_correct":false,"key":"A","sort_order":1,"text":"黃"},{"is_correct":true,"key":"B","sort_order":2,"text":"紅"},{"is_correct":false,"key":"C","sort_order":3,"text":"綠"},{"is_correct":false,"key":"D","sort_order":4,"text":"藍"}]'::jsonb),
  ('0f8e7ec7-6261-cfc8-55b6-1985bc0cec95', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3116', 'section', '下列有關色彩性質的敘述，何者錯誤？', '明度是指色彩的明暗程度，而色彩飽和的程度稱為彩度。故選項C錯誤。', 16, '[{"is_correct":false,"key":"A","sort_order":1,"text":"H、V、C是指色相、明度、彩度"},{"is_correct":false,"key":"B","sort_order":2,"text":"色相是指波長不同所引起的色彩表相"},{"is_correct":true,"key":"C","sort_order":3,"text":"明度是指色彩飽和的程度"},{"is_correct":false,"key":"D","sort_order":4,"text":"彩度是指色彩鮮豔的程度"}]'::jsonb),
  ('4a456e60-7308-031b-2f95-a4e1e4a62622', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3117', 'section', '某純色若加入同明度的灰色，其產生的變化是：', '純色加入同明度的灰色，其明度保持不變，但純度下降，導致彩度變低。故選項A正確。', 17, '[{"is_correct":true,"key":"A","sort_order":1,"text":"明度不變、彩度變低"},{"is_correct":false,"key":"B","sort_order":2,"text":"明度、彩度均變高"},{"is_correct":false,"key":"C","sort_order":3,"text":"明度變低、彩度不變"},{"is_correct":false,"key":"D","sort_order":4,"text":"明度、彩度均不變"}]'::jsonb),
  ('8527f95b-4fc2-86be-ec73-3f36ef45d8be', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3118', 'section', '欲將純紅色與黑色或白色依不同比例調色，請問下列何者彩度最高？', '黑色與白色皆為無彩色，加入的無彩色比例愈低，彩度愈高。20％黑色影響最小，彩度最高。故選項A正確。', 18, '[{"is_correct":true,"key":"A","sort_order":1,"text":"80％純紅色＋20％黑色"},{"is_correct":false,"key":"B","sort_order":2,"text":"60％純紅色＋40％黑色"},{"is_correct":false,"key":"C","sort_order":3,"text":"40％純紅色＋60％白色"},{"is_correct":false,"key":"D","sort_order":4,"text":"20％純紅色＋80％白色"}]'::jsonb),
  ('12e5553f-58f4-7145-837a-8e3a1ed2277b', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3119', 'section', '關於色彩三屬性的描述，下列何者錯誤？', '某一色相加入白色顏料後，明度會增高，但純度下降，彩度會降低。故選項C錯誤。', 19, '[{"is_correct":false,"key":"A","sort_order":1,"text":"色相指的是色彩的相貌，如紅、黃、藍等"},{"is_correct":false,"key":"B","sort_order":2,"text":"某一色相加入黑色顏料後，明度降低、彩度亦降低"},{"is_correct":true,"key":"C","sort_order":3,"text":"某一色相加入白色顏料後，明度增高、彩度亦增高"},{"is_correct":false,"key":"D","sort_order":4,"text":"A色為純紅40％＋白60％，B色為純紅60％＋黑40％，所以A色明度高於B色"}]'::jsonb),
  ('07aca0bc-f945-c631-2b3e-5edee66bbf09', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3120', 'section', '下列何者不是美國語言學家柏林（Berlin）提出的基本色名（Basic Color）？', '柏林提出的11個基本色名包含黑、白、紅、黃、綠、藍、棕、紫、粉紅、橙、灰。米色不包含在內。故選項D錯誤。', 20, '[{"is_correct":false,"key":"A","sort_order":1,"text":"黑色"},{"is_correct":false,"key":"B","sort_order":2,"text":"粉紅色"},{"is_correct":false,"key":"C","sort_order":3,"text":"灰色"},{"is_correct":true,"key":"D","sort_order":4,"text":"米色"}]'::jsonb),
  ('8dcc820e-428f-53b5-b2d2-341e74b14711', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3121', 'section', '以動植物、人名或地名，例如鮭魚紅、芥末綠、土耳其藍等進行色彩命名的方式稱為？', '以動植物、人名或地名等具體事物來命名的色彩稱為固有色名。系統色名則是依據色彩屬性系統化命名。故選項C正確。', 21, '[{"is_correct":false,"key":"A","sort_order":1,"text":"基本色名"},{"is_correct":false,"key":"B","sort_order":2,"text":"系統色名"},{"is_correct":true,"key":"C","sort_order":3,"text":"固有色名"},{"is_correct":false,"key":"D","sort_order":4,"text":"特殊色名"}]'::jsonb),
  ('f1d27ed7-2914-cbd6-9ab0-0b6e72b8e0c3', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3122', 'section', '「丹青」、「胭脂紅」、「帛丹黃」是屬於何種色彩命名法？', '丹青、胭脂紅、帛丹黃皆為中國古代流傳下來的特定色彩名稱，屬於傳統固有色名。故選項D正確。', 22, '[{"is_correct":false,"key":"A","sort_order":1,"text":"系統色名"},{"is_correct":false,"key":"B","sort_order":2,"text":"特殊色名"},{"is_correct":false,"key":"C","sort_order":3,"text":"基本色名"},{"is_correct":true,"key":"D","sort_order":4,"text":"傳統色名"}]'::jsonb),
  ('6e00a234-be4f-5017-3b11-5f46948850cc', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3123', 'section', '下列色彩名，何者不是固有色名稱？', '淡黃屬於系統色名（修飾詞+基本色）。洋紅、檸檬黃、孔雀藍皆為具體事物命名的固有色名。故選項B錯誤。', 23, '[{"is_correct":false,"key":"A","sort_order":1,"text":"洋紅"},{"is_correct":true,"key":"B","sort_order":2,"text":"淡黃"},{"is_correct":false,"key":"C","sort_order":3,"text":"檸檬黃"},{"is_correct":false,"key":"D","sort_order":4,"text":"孔雀藍"}]'::jsonb),
  ('94300c94-1a97-d42d-5f99-09cb39a6e2d7', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3124', 'section', '用科學的觀念將色彩以系統的方式作為色彩名稱，如淡藍、深黃、豔紅等，稱為：', '用科學觀念將色彩系統化命名，如加上淡、深、豔等修飾詞，稱為系統色名。固有色名則是不具系統性的慣用名。故選項A正確。', 24, '[{"is_correct":true,"key":"A","sort_order":1,"text":"系統色名"},{"is_correct":false,"key":"B","sort_order":2,"text":"慣用色名"},{"is_correct":false,"key":"C","sort_order":3,"text":"傳統色名"},{"is_correct":false,"key":"D","sort_order":4,"text":"固有色名"}]'::jsonb),
  ('27ffd5b7-3c71-2813-e979-ab469344923f', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3125', 'section', '「臺灣紅」屬於何種色彩命名法？', '「臺灣紅」是以特定地域與文化意象命名的特定色彩，屬於固有色名。故選項A正確。', 25, '[{"is_correct":true,"key":"A","sort_order":1,"text":"固有色名"},{"is_correct":false,"key":"B","sort_order":2,"text":"基本色名"},{"is_correct":false,"key":"C","sort_order":3,"text":"系統色名"},{"is_correct":false,"key":"D","sort_order":4,"text":"標準色名"}]'::jsonb),
  ('e8babf9a-3390-c926-545e-416147a2b624', 'f929cde5-c294-46ce-5faf-c866b3cb9583', 'QB3126', 'section', '以下有關色彩命名的敘述，何者錯誤？', '「薰衣草紫」是源自西方的固有色名，並非中國傳統色名。故選項A錯誤。', 26, '[{"is_correct":true,"key":"A","sort_order":1,"text":"「薰衣草紫」（Lavender）是中國傳統色名"},{"is_correct":false,"key":"B","sort_order":2,"text":"引用植物名稱作為色彩名，屬於固有色名，例如柳綠"},{"is_correct":false,"key":"C","sort_order":3,"text":"「紫紅」意為帶紫的紅色，屬於系統色名"},{"is_correct":false,"key":"D","sort_order":4,"text":"慣用色名大多引用自生活上較常見或常用的物體名稱"}]'::jsonb),
  ('ef1c2e26-1b4f-ed15-251e-493ac26b7dfe', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3201', 'section', '最早提出色彩排列系統化理論的學者是？', '佛西士（Forsius）於1611年最早提出色彩排列系統化的理論。伊登、奧圖倫格等人則是較晚期的學者。故選項A正確。', 1, '[{"is_correct":true,"key":"A","sort_order":1,"text":"佛西士（Forsius）"},{"is_correct":false,"key":"B","sort_order":2,"text":"奧圖倫格（P. Otto Runge）"},{"is_correct":false,"key":"C","sort_order":3,"text":"伊登（Johannes Itten）"},{"is_correct":false,"key":"D","sort_order":4,"text":"拉伯隆（J. C. Le Blon）"}]'::jsonb),
  ('96af43ff-11c7-cd48-fb3b-f33a8460d2e8', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3202', 'section', '某色在色相環上是舉足輕重的色彩，但在光譜上卻找不到，請問這個色彩是？', '紅紫色為光譜外色彩，無法在自然光譜中找到，是由紅光與紫光混合而成，在色相環上具重要地位。故選項B正確。', 2, '[{"is_correct":false,"key":"A","sort_order":1,"text":"金色"},{"is_correct":true,"key":"B","sort_order":2,"text":"紅紫色"},{"is_correct":false,"key":"C","sort_order":3,"text":"黃綠色"},{"is_correct":false,"key":"D","sort_order":4,"text":"黑白色"}]'::jsonb),
  ('aedef3fe-7066-b6e1-db3b-42d3bd71c256', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3203', 'section', '色相環上通過圓心相對的兩個色彩互稱為：', '色相環上通過圓心，相對180度的兩個色彩互為補色，混合後會形成無彩色。故選項B正確。', 3, '[{"is_correct":false,"key":"A","sort_order":1,"text":"曖昧色"},{"is_correct":true,"key":"B","sort_order":2,"text":"補色"},{"is_correct":false,"key":"C","sort_order":3,"text":"等色相"},{"is_correct":false,"key":"D","sort_order":4,"text":"類似色"}]'::jsonb),
  ('625293c5-00fe-25f9-4e47-040a38063065', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3204', 'section', '觀察色立體之「等色相面」時，可發現同一垂直軸的各色，其何種屬性是一樣的？', '在色立體的等色相面上，同一垂直軸代表相同的彩度，垂直位置高低則代表明度變化。故選項D正確。', 4, '[{"is_correct":false,"key":"A","sort_order":1,"text":"色調"},{"is_correct":false,"key":"B","sort_order":2,"text":"色相"},{"is_correct":false,"key":"C","sort_order":3,"text":"明度"},{"is_correct":true,"key":"D","sort_order":4,"text":"彩度"}]'::jsonb),
  ('16bc38f9-0974-9873-0ec6-6c612bb83ff9', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3205', 'section', '色彩在等色相面上的分布位置，下列何者正確？', '淺色（明色）分布於等色相面的上方邊緣；深色在下方邊緣；濁色則靠近內部無彩色軸。故選項B正確。', 5, '[{"is_correct":false,"key":"A","sort_order":1,"text":"明色分布於等色相面外圍邊緣區域，並靠近下方"},{"is_correct":true,"key":"B","sort_order":2,"text":"淺色分布於等色相面外圍邊緣區域，並靠近上方"},{"is_correct":false,"key":"C","sort_order":3,"text":"深色分布於等色相面外圍邊緣區域，並靠近上方或下方"},{"is_correct":false,"key":"D","sort_order":4,"text":"濁色分布於等色相面外圍邊緣區域，距離明度軸最遠的地方"}]'::jsonb),
  ('f8db77f8-f50a-56b8-5a68-147e898364a4', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3206', 'section', '色彩的三屬性依性質有系統地排列，形成三度空間的結構稱為：', '將色彩的色相、明度、彩度三屬性依性質有系統排列，形成的三維空間結構稱為色立體。故選項B正確。', 6, '[{"is_correct":false,"key":"A","sort_order":1,"text":"色環"},{"is_correct":true,"key":"B","sort_order":2,"text":"色立體"},{"is_correct":false,"key":"C","sort_order":3,"text":"色相"},{"is_correct":false,"key":"D","sort_order":4,"text":"三原色"}]'::jsonb),
  ('a3e7f5cf-8216-070a-62ac-2372af6b2e72', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3207', 'section', '色立體（Color Solid）中心軸的名稱，下列何者為非？', '色立體的中心軸代表無彩色的明度階段，從黑到白，不包含彩度。故選項A錯誤。', 7, '[{"is_correct":true,"key":"A","sort_order":1,"text":"彩度階段"},{"is_correct":false,"key":"B","sort_order":2,"text":"明度階段"},{"is_correct":false,"key":"C","sort_order":3,"text":"垂直軸"},{"is_correct":false,"key":"D","sort_order":4,"text":"無彩色階段"}]'::jsonb),
  ('d11a2212-544c-a02a-15e9-8a256e885498', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3208', 'section', '色立體的基本結構，如圖所示，下列組合何者正確？', '色立體結構中，愈往上方明度愈高（白），愈往外圍彩度愈高（鮮豔）。故選項D正確。', 8, '[{"is_correct":false,"key":"A","sort_order":1,"text":"明度愈高"},{"is_correct":false,"key":"B","sort_order":2,"text":"彩度愈低"},{"is_correct":false,"key":"C","sort_order":3,"text":"明度愈低"},{"is_correct":true,"key":"D","sort_order":4,"text":"彩度愈高"}]'::jsonb),
  ('ef3dc883-2000-7128-6450-6bab8a6885c1', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3209', 'section', '關於色立體的敘述，下列何者不正確？', '色立體包含了所有色彩，但不同色彩體系（如曼塞爾、PCCS）的色立體形態各異，並非完全相同。故選項A錯誤。', 9, '[{"is_correct":true,"key":"A","sort_order":1,"text":"色立體包含了所有的色彩，是認識色彩及色彩計畫與管理上的良好工具"},{"is_correct":false,"key":"B","sort_order":2,"text":"常用色彩體系的明度與彩度值不同，因此各色彩體系的色立體形態均不相同"},{"is_correct":false,"key":"C","sort_order":3,"text":"愈往上方則色彩的明度愈高，愈往下方則色彩的明度愈低"},{"is_correct":false,"key":"D","sort_order":4,"text":"愈往中心軸方向則色彩的彩度愈低，愈往外緣則彩度愈高"}]'::jsonb),
  ('aba6e742-53bc-83cb-8feb-39f6f1695e22', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3210', 'section', '對於色立體的敘述，下列何者正確？', '19世紀初德國人奧圖倫格最先構想出球狀的色立體。中心軸向下明度應為愈低（黑）。故選項B正確。', 10, '[{"is_correct":false,"key":"A","sort_order":1,"text":"以明度階段為中心，向下明度愈高"},{"is_correct":true,"key":"B","sort_order":2,"text":"19世紀初德國人奧圖倫格（P. Otto Runge）最先構想出球狀的色立體"},{"is_correct":false,"key":"C","sort_order":3,"text":"由中心軸愈向外圍，色彩彩度愈低"},{"is_correct":false,"key":"D","sort_order":4,"text":"具有色調（Tone）概念，可方便設計師或畫家挑選配對色彩"}]'::jsonb),
  ('bc928f5c-f46b-8088-39bf-1d7dba1a3fa5', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3211', 'section', '以色光混色為主的色彩體系是：', 'CIE表色系是以色光混色（XYZ）為基礎，利用光學儀器測量的科學化表色系。故選項D正確。', 11, '[{"is_correct":false,"key":"A","sort_order":1,"text":"Munsell"},{"is_correct":false,"key":"B","sort_order":2,"text":"PCCS"},{"is_correct":false,"key":"C","sort_order":3,"text":"NCS"},{"is_correct":true,"key":"D","sort_order":4,"text":"CIE"}]'::jsonb),
  ('39cebacd-4390-2262-de52-94df30db5f46', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3212', 'section', '關於顯色系的敘述，下列何者錯誤？', '顯色系（如曼塞爾、PCCS）以色票比對為主；混色系（如CIE）透過儀器測量，較為精確科學。故選項D錯誤。', 12, '[{"is_correct":false,"key":"A","sort_order":1,"text":"屬於色料的表色系統"},{"is_correct":false,"key":"B","sort_order":2,"text":"以NCS、曼塞爾、PCCS表色系為代表"},{"is_correct":false,"key":"C","sort_order":3,"text":"以目測的方式比對標準色票和色樣之間的關係"},{"is_correct":true,"key":"D","sort_order":4,"text":"測色較混色系精確、科學，使用也較為普遍"}]'::jsonb),
  ('6f4c69fe-7540-e50a-9b5f-96bbc05b05f9', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3213', 'section', '目前國際間誤差最小、最科學化的表色系為：', 'CIE表色系為國際照明委員會制定，是目前國際間誤差最小、最科學化的測色標準。故選項D正確。', 13, '[{"is_correct":false,"key":"A","sort_order":1,"text":"曼塞爾（Munsell）表色系"},{"is_correct":false,"key":"B","sort_order":2,"text":"NCS表色系"},{"is_correct":false,"key":"C","sort_order":3,"text":"PCCS表色系"},{"is_correct":true,"key":"D","sort_order":4,"text":"CIE表色系"}]'::jsonb),
  ('6ad5b46e-3cf1-bffa-5328-b9706bb751a5', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3214', 'section', '下列表色系何者適用於色彩工程與管理上？', 'CIE表色系極為精確，廣泛適用於色彩工程、色彩管理與數位色彩校正等領域。故選項D正確。', 14, '[{"is_correct":false,"key":"A","sort_order":1,"text":"PCCS表色系"},{"is_correct":false,"key":"B","sort_order":2,"text":"NCS自然表色系"},{"is_correct":false,"key":"C","sort_order":3,"text":"Munsell表色系"},{"is_correct":true,"key":"D","sort_order":4,"text":"CIE表色系"}]'::jsonb),
  ('7714e6fb-04d7-cb86-c483-7afae62bf8b1', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3215', 'section', 'CIE表色系中以Yxy方式表色時，Y表示：', '在CIE Yxy表色法中，Y代表明度（亮度），x與y代表色度座標。故選項B正確。', 15, '[{"is_correct":false,"key":"A","sort_order":1,"text":"純色量"},{"is_correct":true,"key":"B","sort_order":2,"text":"明度"},{"is_correct":false,"key":"C","sort_order":3,"text":"飽和度"},{"is_correct":false,"key":"D","sort_order":4,"text":"色相"}]'::jsonb),
  ('bb7e67e8-30a1-92ed-3611-5182d0183075', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3216', 'section', 'CIE表色系中，L*a*b*表色法中的L是表示？', '在CIE L*a*b*表色法中，L*代表明度（Lightness），a*與b*代表色度。故選項A正確。', 16, '[{"is_correct":true,"key":"A","sort_order":1,"text":"明度"},{"is_correct":false,"key":"B","sort_order":2,"text":"彩度"},{"is_correct":false,"key":"C","sort_order":3,"text":"色相"},{"is_correct":false,"key":"D","sort_order":4,"text":"色調"}]'::jsonb),
  ('70bc6b06-872f-1e27-2ff6-1572dd361802', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3217', 'section', '對於CIELAB表色系，下列敘述何者為非？', 'CIELAB中，a*代表從紅到綠的色彩分量，b*代表從黃到藍的色彩分量。故選項B敘述錯誤。', 17, '[{"is_correct":false,"key":"A","sort_order":1,"text":"為CIE於1976年制定的一種色光表色法"},{"is_correct":true,"key":"B","sort_order":2,"text":"以色光三原色R、G、B為基本色"},{"is_correct":false,"key":"C","sort_order":3,"text":"a代表從紅到綠的色彩分量"},{"is_correct":false,"key":"D","sort_order":4,"text":"b代表從黃到藍的色彩分量"}]'::jsonb),
  ('83a804fd-5138-757f-fe1f-30fe3aea6702', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3218', 'section', '有關CIE色彩體系的敘述，下列何者不正確？', 'CIE 1931 XYZ表色系中，Y代表明度與反射率，Z代表藍色刺激值，並非色光反射率。故選項C敘述錯誤。', 18, '[{"is_correct":false,"key":"A","sort_order":1,"text":"1931年以楊格（Young）、赫姆豪茲（Helmholtz）的色光三原色理論為基礎而發展"},{"is_correct":false,"key":"B","sort_order":2,"text":"1931年以色光三原色R、G、B為準，設定三種座標X、Y、Z的刺激值，故又稱XYZ表色系"},{"is_correct":true,"key":"C","sort_order":3,"text":"XYZ表色系之X、Y、Z刺激值也可以使用Z、x、y來表示色彩，大寫Z代表色光反射率，小寫x、y是色度圖中X座標和Y座標上的數值"},{"is_correct":false,"key":"D","sort_order":4,"text":"1976年以人類視覺四原色（紅、黃、綠、藍）為基礎發表CIELAB，又稱CIE 1976LAB表色系"}]'::jsonb),
  ('b7b0e324-2e70-e4da-6908-8fc4777465a8', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3219', 'section', '如圖之色相環屬於何種表色系？', '該圖為伊登（Itten）十二色相環，以紅黃藍三原色為基礎發展而成。故選項C正確。', 19, '[{"is_correct":false,"key":"A","sort_order":1,"text":"PCCS表色系"},{"is_correct":false,"key":"B","sort_order":2,"text":"曼塞爾（Munsell）表色系"},{"is_correct":true,"key":"C","sort_order":3,"text":"伊登（Itten）表色系"},{"is_correct":false,"key":"D","sort_order":4,"text":"CIE表色系"}]'::jsonb),
  ('6a464dc7-5ff9-7b76-005c-812517dccc90', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3220', 'section', '伊登十二色相環中的三原色是指？', '伊登十二色相環的三原色為色料三原色：紅、黃、藍。故選項D正確。', 20, '[{"is_correct":false,"key":"A","sort_order":1,"text":"紅、綠、黃"},{"is_correct":false,"key":"B","sort_order":2,"text":"紅、綠、紫"},{"is_correct":false,"key":"C","sort_order":3,"text":"黃、紫、藍"},{"is_correct":true,"key":"D","sort_order":4,"text":"紅、黃、藍"}]'::jsonb),
  ('c8f87bfe-d87e-af58-5e1d-f57a1e3914db', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3221', 'section', '伊登色相環中，下列何者為二次色？', '在伊登色相環中，綠色是由黃色與藍色混合而成的二次色。故選項C正確。', 21, '[{"is_correct":false,"key":"A","sort_order":1,"text":"紅"},{"is_correct":false,"key":"B","sort_order":2,"text":"黃"},{"is_correct":true,"key":"C","sort_order":3,"text":"綠"},{"is_correct":false,"key":"D","sort_order":4,"text":"紅紫"}]'::jsonb),
  ('6eca63ec-54ab-13dd-3c78-b6f1302ef8e0', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3222', 'section', '伊登色相環中，下列何者不是第三次色？', '紫色是由紅色與藍色混合而成的二次色；第三次色是由原色與二次色混合而成。故選項D錯誤。', 22, '[{"is_correct":false,"key":"A","sort_order":1,"text":"紅紫"},{"is_correct":false,"key":"B","sort_order":2,"text":"黃橙"},{"is_correct":false,"key":"C","sort_order":3,"text":"藍綠"},{"is_correct":true,"key":"D","sort_order":4,"text":"紫"}]'::jsonb),
  ('378762aa-1b00-e806-ec4b-b63fd31592d3', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3223', 'section', '下列何種色彩體系之色立體外觀為「圓球體」？', '伊登表色系的色立體外觀呈現對稱的圓球體。曼塞爾為不規則形，PCCS為斜橢圓形。故選項C正確。', 23, '[{"is_correct":false,"key":"A","sort_order":1,"text":"PCCS表色系"},{"is_correct":false,"key":"B","sort_order":2,"text":"曼塞爾表色系"},{"is_correct":true,"key":"C","sort_order":3,"text":"伊登表色系"},{"is_correct":false,"key":"D","sort_order":4,"text":"CIEXYE表色系"}]'::jsonb),
  ('0de79660-88d5-1cb0-8ea3-c277071e9085', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3224', 'section', '關於伊登表色系特色之敘述，下列何者為非？', '伊登表色系屬於依賴色票或顏料比對的顯色系，並非科學化的混色系。故選項D錯誤。', 24, '[{"is_correct":false,"key":"A","sort_order":1,"text":"表色簡易明瞭，為初學色彩之最佳教材"},{"is_correct":false,"key":"B","sort_order":2,"text":"色相環直徑兩相對色彩是補色關係"},{"is_correct":false,"key":"C","sort_order":3,"text":"基本色有三色，色相環共有12色，補色對共有六對"},{"is_correct":true,"key":"D","sort_order":4,"text":"表色方式科學化，屬於混色系"}]'::jsonb),
  ('8697e6ee-e89a-7e4d-15c6-747fcbbfe8be', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3225', 'section', '曼塞爾（Munsell）表色系是以哪五個基本顏色，平均配置於色相環上？', '曼塞爾表色系的五原色為紅（R）、黃（Y）、綠（G）、藍（B）、紫（P）。故選項D正確。', 25, '[{"is_correct":false,"key":"A","sort_order":1,"text":"R、Y、G、B、O"},{"is_correct":false,"key":"B","sort_order":2,"text":"R、Y、V、B、P"},{"is_correct":false,"key":"C","sort_order":3,"text":"R、M、G、B、P"},{"is_correct":true,"key":"D","sort_order":4,"text":"R、Y、G、B、P"}]'::jsonb),
  ('5259953a-ab7c-9a8e-bfd4-e6c85aac35d5', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3226', 'section', '曼塞爾表色系是由「心理五原色」發展而來，提出心理五原色的學者是？', '本題測驗曼塞爾表色系的理論基礎。曼塞爾表色系是以紅、黃、綠、藍、紫五種顏色作為基本色相，此概念在部分色彩學教材中被稱為「心理五原色」，並將其理論發展溯源至赫姆豪茲（Helmholtz）的視覺色彩相關研究。因此，依據此學說脈絡，本題將提出心理五原色的學者對應為赫姆豪茲。故選項D正確。', 26, '[{"is_correct":false,"key":"A","sort_order":1,"text":"牛頓（Newton）"},{"is_correct":false,"key":"B","sort_order":2,"text":"楊格（Young）"},{"is_correct":false,"key":"C","sort_order":3,"text":"赫林（Hering）"},{"is_correct":true,"key":"D","sort_order":4,"text":"赫姆豪茲（Helmholtz）"}]'::jsonb),
  ('55531c78-492b-df38-147d-fb926f3d65c1', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3227', 'section', '曼塞爾表色系的表色法中，何者為代表純紅色色相的符號？', '在曼塞爾表色系中，5R代表純紅色，10R則偏黃。故選項C正確。', 27, '[{"is_correct":false,"key":"A","sort_order":1,"text":"R"},{"is_correct":false,"key":"B","sort_order":2,"text":"2R"},{"is_correct":true,"key":"C","sort_order":3,"text":"5R"},{"is_correct":false,"key":"D","sort_order":4,"text":"10R"}]'::jsonb),
  ('42e1312d-5d5c-17d6-158e-35aeba618c99', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3228', 'section', '曼塞爾表色系，明度分為幾個階段？', '曼塞爾表色系的明度階段從純黑（N0）到純白（N10），共分為11個階段。故選項A正確。', 28, '[{"is_correct":true,"key":"A","sort_order":1,"text":"11"},{"is_correct":false,"key":"B","sort_order":2,"text":"9"},{"is_correct":false,"key":"C","sort_order":3,"text":"8"},{"is_correct":false,"key":"D","sort_order":4,"text":"5"}]'::jsonb),
  ('496ae5c9-2547-758c-ca20-19b9b716b41b', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3229', 'section', '曼塞爾表色系明度的表示法，把黑色定為：', '曼塞爾明度表示法中，將理想的純黑色定為N0，純白色定為N10。故選項A正確。', 29, '[{"is_correct":true,"key":"A","sort_order":1,"text":"N0"},{"is_correct":false,"key":"B","sort_order":2,"text":"N1.5"},{"is_correct":false,"key":"C","sort_order":3,"text":"N5"},{"is_correct":false,"key":"D","sort_order":4,"text":"N10"}]'::jsonb),
  ('c169fdac-f792-27bb-c674-95481d52c1be', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3230', 'section', '曼塞爾表色系色立體的外形呈：', '由於各色相的最高彩度不同，曼塞爾色立體的外形呈現不規則狀。故選項C正確。', 30, '[{"is_correct":false,"key":"A","sort_order":1,"text":"複圓錐形"},{"is_correct":false,"key":"B","sort_order":2,"text":"圓球體"},{"is_correct":true,"key":"C","sort_order":3,"text":"不規則形"},{"is_correct":false,"key":"D","sort_order":4,"text":"斜橢圓形"}]'::jsonb),
  ('4a387266-5272-2113-446f-7300a6b53cfe', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3231', 'section', '色立體因為形態類似樹形，故又稱為色彩樹（Color Tree）的色彩體系是？', '曼塞爾色立體因各色相彩度延伸長度不一，形態類似樹木，故又稱色彩樹。故選項B正確。', 31, '[{"is_correct":false,"key":"A","sort_order":1,"text":"伊登表色系"},{"is_correct":true,"key":"B","sort_order":2,"text":"曼塞爾表色系"},{"is_correct":false,"key":"C","sort_order":3,"text":"PCCS表色系"},{"is_correct":false,"key":"D","sort_order":4,"text":"NCS表色系"}]'::jsonb),
  ('40786c17-bb51-d1c4-c6c5-ba4ab1922b94', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3232', 'section', '下列何種表色方式屬於曼塞爾表色系之呈色方式？', '5R 4/6符合曼塞爾表色法「H V/C」（色相 明度/彩度）的格式。故選項A正確。', 32, '[{"is_correct":true,"key":"A","sort_order":1,"text":"5R 4/6"},{"is_correct":false,"key":"B","sort_order":2,"text":"2R-4.5-9S"},{"is_correct":false,"key":"C","sort_order":3,"text":"C50Y100M60"},{"is_correct":false,"key":"D","sort_order":4,"text":"RED"}]'::jsonb),
  ('3ed8073a-50a9-4a66-d872-ed3e62f838d1', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3233', 'section', '曼塞爾表色系的表色法，5R 4/14中之4是表示：', '在5R 4/14中，5R為色相，4代表明度（V），14代表彩度（C）。故選項B正確。', 33, '[{"is_correct":false,"key":"A","sort_order":1,"text":"色相"},{"is_correct":true,"key":"B","sort_order":2,"text":"明度"},{"is_correct":false,"key":"C","sort_order":3,"text":"彩度"},{"is_correct":false,"key":"D","sort_order":4,"text":"色調"}]'::jsonb),
  ('c93073f5-bee6-bf7c-828d-45daf6010113', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3234', 'section', '曼塞爾表色系中，下列色彩何者最鮮豔？', '彩度數值越大代表色彩越鮮豔。5R 4/14的彩度為14，是選項中最高的。故選項A正確。', 34, '[{"is_correct":true,"key":"A","sort_order":1,"text":"5R 4/14"},{"is_correct":false,"key":"B","sort_order":2,"text":"5YR 2/10"},{"is_correct":false,"key":"C","sort_order":3,"text":"5G 5/8"},{"is_correct":false,"key":"D","sort_order":4,"text":"5B 6/8"}]'::jsonb),
  ('fd894363-68e9-d6e4-efb7-437aed3e6dc3', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3235', 'section', '曼塞爾表色系的表色法中，5R 4/6和5BG 7/4兩色比較，依符號可知，5R 4/6比5BG 7/4：', '5R 4/6（明度4，彩度6）與5BG 7/4（明度7，彩度4）相比，前者明度較低，彩度較高。故選項A正確。', 35, '[{"is_correct":true,"key":"A","sort_order":1,"text":"明度低、彩度高"},{"is_correct":false,"key":"B","sort_order":2,"text":"明度高、彩度高"},{"is_correct":false,"key":"C","sort_order":3,"text":"明度低、彩度低"},{"is_correct":false,"key":"D","sort_order":4,"text":"明度高、彩度低"}]'::jsonb),
  ('1d337530-27f5-250f-96e4-f56a8bfa1a21', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3236', 'section', '顯色系中，最通用、最科學之表色系為？', '曼塞爾表色系是目前國際間最通用、最科學的顯色系（色票系統）。故選項B正確。', 36, '[{"is_correct":false,"key":"A","sort_order":1,"text":"PCCS表色系"},{"is_correct":true,"key":"B","sort_order":2,"text":"Munsell表色系"},{"is_correct":false,"key":"C","sort_order":3,"text":"NCS表色系"},{"is_correct":false,"key":"D","sort_order":4,"text":"CIE表色系"}]'::jsonb),
  ('caf9a58b-c78a-bd5e-df99-bce34dab5400', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3237', 'section', '中、美、日等國的國家工業規格中，色彩的標示依據是？', '曼塞爾表色系被中、美、日等國家的工業規格（如JIS）採納為標準表色法。故選項C正確。', 37, '[{"is_correct":false,"key":"A","sort_order":1,"text":"Itten表色法"},{"is_correct":false,"key":"B","sort_order":2,"text":"NCS表色系"},{"is_correct":true,"key":"C","sort_order":3,"text":"Munsell表色系"},{"is_correct":false,"key":"D","sort_order":4,"text":"PCCS表色系"}]'::jsonb),
  ('ca9e8c45-0f6d-60fd-f2e8-6e163a123903', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3238', 'section', '下列有關曼塞爾表色系的敘述，何者錯誤？', '曼塞爾表色系屬於顯色系（依賴色票），CIE才是最具科學化的混色系。故選項D錯誤。', 38, '[{"is_correct":false,"key":"A","sort_order":1,"text":"經美國光學會（OSA）修正，可作為色彩管理之用"},{"is_correct":false,"key":"B","sort_order":2,"text":"日本工業規格（JIS）採納為測色管理之依據"},{"is_correct":false,"key":"C","sort_order":3,"text":"是最具國際化及學術權威的共通表色系與測色法"},{"is_correct":true,"key":"D","sort_order":4,"text":"可轉換為CIE表色法，是混色系中最具科學化的表色及測色標準"}]'::jsonb),
  ('aa8e5961-2118-621e-02a3-cf911935f961', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3239', 'section', '下列有關曼塞爾表色系的敘述，何者錯誤？', '曼塞爾為美國人。其表色系每一色相以第5等分為代表色，明度N10反射率並非絕對100％。故選項B敘述錯誤。', 39, '[{"is_correct":false,"key":"A","sort_order":1,"text":"曼塞爾出生於美國，曾留學法國，是一位美術老師"},{"is_correct":true,"key":"B","sort_order":2,"text":"表色系中的每一色相之第10等分，為其代表色"},{"is_correct":false,"key":"C","sort_order":3,"text":"表色系中的明度軸最高為N10，是為白色，其反射率是100％"},{"is_correct":false,"key":"D","sort_order":4,"text":"為我國工業標準的表色法"}]'::jsonb),
  ('df719235-5b3a-d84e-bf3a-14f83eb2f25e', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3240', 'section', '日本PCCS表色系中，有關明度軸的敘述，下列何者錯誤？', 'PCCS表色系中，無彩色明度分為9階，黑色編碼為1.5，白色編碼為9.5。故選項D錯誤。', 40, '[{"is_correct":false,"key":"A","sort_order":1,"text":"將黑、灰、白的明度變化分為9個階段"},{"is_correct":false,"key":"B","sort_order":2,"text":"愈往上端明度愈高，愈往下端明度愈低"},{"is_correct":false,"key":"C","sort_order":3,"text":"又稱為「無彩色軸」"},{"is_correct":true,"key":"D","sort_order":4,"text":"黑色編碼為9.5，白色編碼為1.5"}]'::jsonb),
  ('65260d5d-99e5-6e2b-c5e6-2198aa5f1fcc', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3241', 'section', 'PCCS表色系中，2R-4.5-9S的表色意義為：', '2R-4.5-9S代表：色相2R（紅）、明度4.5、彩度9S。故選項A正確。', 41, '[{"is_correct":true,"key":"A","sort_order":1,"text":"色相紅、明度4.5、彩度9"},{"is_correct":false,"key":"B","sort_order":2,"text":"色相紅、黑量4.5、白量9"},{"is_correct":false,"key":"C","sort_order":3,"text":"色相紅、彩度4.5、明度9"},{"is_correct":false,"key":"D","sort_order":4,"text":"色相黃綠、明度4.5、彩度9"}]'::jsonb),
  ('fd542e72-fdef-d425-6c9d-c46af4e64a86', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3242', 'section', 'PCCS表色系的表色法中，下列何者是鮮橙色？', '5O為橙色，8S為高彩度，7.5為中高明度，故5O-7.5-8S代表鮮橙色。故選項A正確。', 42, '[{"is_correct":true,"key":"A","sort_order":1,"text":"5O-7.5-8S"},{"is_correct":false,"key":"B","sort_order":2,"text":"17O-6.5-2S"},{"is_correct":false,"key":"C","sort_order":3,"text":"20V-1.0-6S"},{"is_correct":false,"key":"D","sort_order":4,"text":"12G-2.4-3S"}]'::jsonb),
  ('ee88308c-bda6-c099-8461-5267a18520cc', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3243', 'section', '統合明度與彩度為色調（Tone）概念的色彩體系是？', 'PCCS表色系最大的特色是導入了「色調」（Tone）概念，統合了明度與彩度。故選項D正確。', 43, '[{"is_correct":false,"key":"A","sort_order":1,"text":"伊登表色系"},{"is_correct":false,"key":"B","sort_order":2,"text":"NCS表色系"},{"is_correct":false,"key":"C","sort_order":3,"text":"曼塞爾表色系"},{"is_correct":true,"key":"D","sort_order":4,"text":"PCCS表色系"}]'::jsonb),
  ('a7e721a5-7dcc-9909-5a6b-83132dc5b8be', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3244', 'section', '在PCCS表色系中，「深的」色調之簡稱是？', '在PCCS表色系中，深的色調（Deep tone）簡稱為dp。故選項B正確。', 44, '[{"is_correct":false,"key":"A","sort_order":1,"text":"d"},{"is_correct":true,"key":"B","sort_order":2,"text":"dp"},{"is_correct":false,"key":"C","sort_order":3,"text":"b"},{"is_correct":false,"key":"D","sort_order":4,"text":"dk"}]'::jsonb),
  ('dbef1783-0763-09e3-0a0a-9aeb0e6e4ebb', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3245', 'section', '在PCCS表色系中，色調簡稱「b」是指何種色調？', '在PCCS表色系中，色調簡稱「b」代表bright（明色調）。故選項C正確。', 45, '[{"is_correct":false,"key":"A","sort_order":1,"text":"粉色調"},{"is_correct":false,"key":"B","sort_order":2,"text":"鮮色調"},{"is_correct":true,"key":"C","sort_order":3,"text":"明色調"},{"is_correct":false,"key":"D","sort_order":4,"text":"暗色調"}]'::jsonb),
  ('901fdb7a-461e-9de4-8d2e-414acf9ee89f', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3246', 'section', 'PCCS表色系的色立體呈現：', 'PCCS表色系的色立體因各色相最高彩度位置不同，整體呈現斜橢圓形。故選項A正確。', 46, '[{"is_correct":true,"key":"A","sort_order":1,"text":"斜橢圓形"},{"is_correct":false,"key":"B","sort_order":2,"text":"樹形"},{"is_correct":false,"key":"C","sort_order":3,"text":"複圓錐狀"},{"is_correct":false,"key":"D","sort_order":4,"text":"不規則形"}]'::jsonb),
  ('a98278b5-a8b8-e51e-2f20-9eb87f74638e', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3247', 'section', '關於PCCS表色系的敘述，下列何者不正確？', '各等色相面的彩度階段數量不同，但純色皆設定在彩度9S的位置。故選項C錯誤。', 47, '[{"is_correct":false,"key":"A","sort_order":1,"text":"位於等色相面上方的色彩，明度值越大"},{"is_correct":false,"key":"B","sort_order":2,"text":"各等色相面中，彩度為9S的色彩為純色"},{"is_correct":true,"key":"C","sort_order":3,"text":"各等色相面的彩度階段，數量不相等"},{"is_correct":false,"key":"D","sort_order":4,"text":"在等色相面上，彩度愈高的色彩，其位置愈遠離中心軸"}]'::jsonb),
  ('c1f23a09-30d2-3c64-17f6-7cd7eeb6d702', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3248', 'section', '表色體系中，大量印製多元化配色之色票，兼具設計實用配色及色彩教學功能的色彩體系為？', 'PCCS表色系發行了大量實用色票，廣泛應用於設計實務與色彩教學。故選項D正確。', 48, '[{"is_correct":false,"key":"A","sort_order":1,"text":"Itten表色系"},{"is_correct":false,"key":"B","sort_order":2,"text":"NCS表色系"},{"is_correct":false,"key":"C","sort_order":3,"text":"Munsell表色系"},{"is_correct":true,"key":"D","sort_order":4,"text":"PCCS表色系"}]'::jsonb),
  ('58758b10-d60f-e9dd-897e-37ec595d8d36', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3249', 'section', '關於PCCS表色系的敘述，下列何者錯誤？', 'PCCS明度分9階，彩度分9階，但有彩色共分為12個色調，而非18個。故選項A錯誤。', 49, '[{"is_correct":true,"key":"A","sort_order":1,"text":"明度與彩度階均為9階，因此共有18個色調"},{"is_correct":false,"key":"B","sort_order":2,"text":"表色法「H-V-C」表示「色相－明度－彩度」"},{"is_correct":false,"key":"C","sort_order":3,"text":"日本文省部（教育部）頒定之日本國家教育用的色彩體系"},{"is_correct":false,"key":"D","sort_order":4,"text":"最大特色是色調的概念，使符號、色名、色調可相互運用表示"}]'::jsonb),
  ('f4ca6252-aff2-62e1-b5c6-80082eea125f', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3250', 'section', 'PCCS的表色符號lt20表示何種色彩？', 'lt為light（淺色調），20為藍紫色（V），故lt20表示淺藍紫色。故選項D正確。', 50, '[{"is_correct":false,"key":"A","sort_order":1,"text":"淺綠"},{"is_correct":false,"key":"B","sort_order":2,"text":"鮮紅"},{"is_correct":false,"key":"C","sort_order":3,"text":"藍色"},{"is_correct":true,"key":"D","sort_order":4,"text":"淺藍紫色"}]'::jsonb),
  ('25ce728a-5806-bb32-bb74-38facbcab414', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3251', 'section', '發表於1968年，是英國ICI塗料公司的表色準則，並普遍應用於歐洲的色彩體系是？', 'NCS（自然色彩體系）廣泛應用於歐洲，為瑞典國家工業規格。故選項D正確。', 51, '[{"is_correct":false,"key":"A","sort_order":1,"text":"CIE表色系"},{"is_correct":false,"key":"B","sort_order":2,"text":"PCCS表色系"},{"is_correct":false,"key":"C","sort_order":3,"text":"Itten表色系"},{"is_correct":true,"key":"D","sort_order":4,"text":"NCS表色系"}]'::jsonb),
  ('ac9a0942-f0be-55fc-df14-97107760a695', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3252', 'section', 'NCS表色系的基本色彩是？', 'NCS表色系以赫林四原色為基礎，基本色為白（W）、黑（S）、紅（R）、綠（G）、黃（Y）、藍（B）。故選項A正確。', 52, '[{"is_correct":true,"key":"A","sort_order":1,"text":"W、S、R、G、Y、B六色"},{"is_correct":false,"key":"B","sort_order":2,"text":"R、Y、G、B、P五色"},{"is_correct":false,"key":"C","sort_order":3,"text":"R、O、Y、G、B、P六色"},{"is_correct":false,"key":"D","sort_order":4,"text":"Y、R、UB、SG四色"}]'::jsonb),
  ('5ba1d08a-d6d9-43ce-ab59-24a1eb7ea500', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3253', 'section', '下列何種表色系的色立體外形接近複圓錐體？', 'NCS色立體以黑白為垂直軸，紅綠黃藍為水平軸，外形接近對稱的複圓錐體。故選項D正確。', 53, '[{"is_correct":false,"key":"A","sort_order":1,"text":"CIE表色系"},{"is_correct":false,"key":"B","sort_order":2,"text":"Munsell表色系"},{"is_correct":false,"key":"C","sort_order":3,"text":"PCCS表色系"},{"is_correct":true,"key":"D","sort_order":4,"text":"NCS表色系"}]'::jsonb),
  ('1b072f48-1bbe-cbb9-a219-a5a48c7649df', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3254', 'section', '關於NCS自然色彩體系的表色法S「SC-Φ」之敘述，下列何者正確？', 'NCS表色法S C-Φ依序代表：黑量（S）、彩色量（C）、色相（Φ）。故選項D正確。', 54, '[{"is_correct":false,"key":"A","sort_order":1,"text":"S為色相，C為明度，Φ為彩度"},{"is_correct":false,"key":"B","sort_order":2,"text":"S為彩色量，C為色相，Φ為黑色量"},{"is_correct":false,"key":"C","sort_order":3,"text":"S為白色量，C為黑色量，Φ為彩色量"},{"is_correct":true,"key":"D","sort_order":4,"text":"S為黑色量，C為彩色量，Φ為色相"}]'::jsonb),
  ('1bcf1a91-5480-6e11-8e72-f48c0fa31c03', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3255', 'section', '下列何者是NCS表色系的表色符號？', 'S 3050-Y20R符合NCS表色法格式，表示黑量30，彩色量50，色相為黃帶20％紅。故選項B正確。', 55, '[{"is_correct":false,"key":"A","sort_order":1,"text":"S Y20R-3050"},{"is_correct":true,"key":"B","sort_order":2,"text":"S 3050-Y20R"},{"is_correct":false,"key":"C","sort_order":3,"text":"2R-4.5-9S"},{"is_correct":false,"key":"D","sort_order":4,"text":"5R 4/14"}]'::jsonb),
  ('3bb81cb8-f466-932a-b86d-f1dd86bb7a7d', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3256', 'section', 'NCS表色系的表色法中，下列何者最接近純黃色？', 'Y10R表示黃色帶有10％的紅色，是選項中最接近純黃色的色相。故選項B正確。', 56, '[{"is_correct":false,"key":"A","sort_order":1,"text":"R90B"},{"is_correct":true,"key":"B","sort_order":2,"text":"Y10R"},{"is_correct":false,"key":"C","sort_order":3,"text":"Y90R"},{"is_correct":false,"key":"D","sort_order":4,"text":"B90G"}]'::jsonb),
  ('c229bce2-9ea2-0cc5-351f-ff18e8039174', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3257', 'section', 'NCS表色系的表色法中，S 1080-B50G接近何種色彩？', 'B50G為藍綠色，黑量10、彩色量80代表高彩度，故接近鮮藍綠色。故選項B正確。', 57, '[{"is_correct":false,"key":"A","sort_order":1,"text":"暗藍綠色"},{"is_correct":true,"key":"B","sort_order":2,"text":"鮮藍綠色"},{"is_correct":false,"key":"C","sort_order":3,"text":"淺藍綠色"},{"is_correct":false,"key":"D","sort_order":4,"text":"灰綠色"}]'::jsonb),
  ('61f75743-06aa-bed5-c057-e4d9af1f66fc', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3258', 'section', 'NCS表色系的表色法中，S 2070-Y50R之白色量占總比例多少？', 'S 2070表示黑量20％，彩色量70％，故白色量為100％-20％-70％ = 10％。故選項A正確。', 58, '[{"is_correct":true,"key":"A","sort_order":1,"text":"10％"},{"is_correct":false,"key":"B","sort_order":2,"text":"20％"},{"is_correct":false,"key":"C","sort_order":3,"text":"30％"},{"is_correct":false,"key":"D","sort_order":4,"text":"50％"}]'::jsonb),
  ('ce3417f2-01eb-0ee9-cbda-68048c08942e', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3259', 'section', 'NCS表色系的表色法中，S 2070-Y50R之紅色占總比例多少？', 'Y50R表示色相中紅黃各半。彩色量70％中，紅色佔一半，即70％ × 50％ = 35％。故選項C正確。', 59, '[{"is_correct":false,"key":"A","sort_order":1,"text":"90％"},{"is_correct":false,"key":"B","sort_order":2,"text":"50％"},{"is_correct":true,"key":"C","sort_order":3,"text":"35％"},{"is_correct":false,"key":"D","sort_order":4,"text":"30％"}]'::jsonb),
  ('1e13804b-4c5e-b8bc-ab88-e4ff76702dfb', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3260', 'section', '在NCS表色系色立體中，何種明度區域可以形成較多的色彩階段？', '在NCS色立體中，中明度區域的截面積最大，能形成較多的色彩階段。故選項B正確。', 60, '[{"is_correct":false,"key":"A","sort_order":1,"text":"低明度區"},{"is_correct":true,"key":"B","sort_order":2,"text":"中明度區"},{"is_correct":false,"key":"C","sort_order":3,"text":"高明度區"},{"is_correct":false,"key":"D","sort_order":4,"text":"最低明度區"}]'::jsonb),
  ('188613bb-0a88-17bb-f6a7-85a6f28ff388', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3261', 'section', '下列關於NCS自然色彩體系的敘述，何者正確？', 'NCS色彩體系是以赫林（Hering）的生理四原色說（紅綠、黃藍）為理論依據。故選項B正確。', 61, '[{"is_correct":false,"key":"A","sort_order":1,"text":"為瑞士色彩學家哈德（Hard）與西維克（Sivic）創立的色彩體系"},{"is_correct":true,"key":"B","sort_order":2,"text":"以赫林（Hering）的生理四原色說為色彩理論依據"},{"is_correct":false,"key":"C","sort_order":3,"text":"其色相環為24色色相環，依序1～24號編號"},{"is_correct":false,"key":"D","sort_order":4,"text":"採用紅－黃、綠－藍、黑－白等三組基本色為色立體的三個座標軸"}]'::jsonb),
  ('b65dc72f-b0a8-8f01-2233-1353760e29c5', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3262', 'section', '下列表色系之色立體形狀的對照，下列何者錯誤？', 'PCCS色立體呈斜橢圓形，曼塞爾色立體才是不規則樹形。故選項C錯誤。', 62, '[{"is_correct":false,"key":"A","sort_order":1,"text":"伊登（Itten）：圓球體"},{"is_correct":false,"key":"B","sort_order":2,"text":"曼塞爾（Munsell）：不規則形"},{"is_correct":true,"key":"C","sort_order":3,"text":"PCCS：樹形"},{"is_correct":false,"key":"D","sort_order":4,"text":"NCS：複圓錐體"}]'::jsonb),
  ('f1d3d655-7b60-6699-e0d3-94ae6b22478e', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3263', 'section', '「8P 4/6」、「2R-4.5-9S」、「S 3050-Y20R」各是指何種色彩體系的表色方法？', '8P 4/6為曼塞爾；2R-4.5-9S為PCCS；S 3050-Y20R為NCS表色法。故選項D正確。', 63, '[{"is_correct":false,"key":"A","sort_order":1,"text":"曼塞爾表色系、NCS表色系、PCCS表色系"},{"is_correct":false,"key":"B","sort_order":2,"text":"PCCS表色系、NCS表色系、CIE表色系"},{"is_correct":false,"key":"C","sort_order":3,"text":"伊登表色系、PCCS表色系、NCS表色系"},{"is_correct":true,"key":"D","sort_order":4,"text":"曼塞爾表色系、PCCS表色系、NCS表色系"}]'::jsonb),
  ('c3790c8a-c96d-f518-64cf-6620fafb1853', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3264', 'section', '有關色彩體系的敘述，下列何者錯誤？', 'CIEXYZ為混色系，無實體色相環概念；曼塞爾發展出100色色相環。故選項A錯誤。', 64, '[{"is_correct":true,"key":"A","sort_order":1,"text":"CIEXYZ表色系以色光三原色為基礎，發展出100色色相環"},{"is_correct":false,"key":"B","sort_order":2,"text":"曼塞爾表色系以赫姆豪茲（Helmholtz）心理五原色為基礎，發展出100色的色相環"},{"is_correct":false,"key":"C","sort_order":3,"text":"伊登表色系以三原色為基礎，發展出12色的色相環"},{"is_correct":false,"key":"D","sort_order":4,"text":"PCCS表色系以色光及色料三原色為基礎，發展出24色的色相環"}]'::jsonb),
  ('737eca8b-3526-6367-7e5f-b23575692ab4', '036f87e5-edc3-6500-604b-76fef106db70', 'QB3265', 'section', '有關色彩體系的敘述，下列何者正確？', '伊登表色系簡明易懂，對於混色概念及類似色、對比色的教學十分重要。故選項D正確。', 65, '[{"is_correct":false,"key":"A","sort_order":1,"text":"NCS表色系特別重視色調概念"},{"is_correct":false,"key":"B","sort_order":2,"text":"日本色研實用配色體系以印刷四原色為基礎，從實用的角度發展而成"},{"is_correct":false,"key":"C","sort_order":3,"text":"曼塞爾表色系為德國工業標準的統一表色法"},{"is_correct":true,"key":"D","sort_order":4,"text":"伊登表色系對混色概念及色相環中類似色與對比色的了解十分重要"}]'::jsonb),
  ('36a75131-73ba-cd03-2701-66d5603f9b8f', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3301', 'section', '在電腦影像處理技術中，色光的混合能產生多少種不同的色彩？', 'RGB各分為256色階，混合可產生 256 × 256 × 256 = 16，777，216 種色彩。故選項B正確。', 1, '[{"is_correct":false,"key":"A","sort_order":1,"text":"128×128×128"},{"is_correct":true,"key":"B","sort_order":2,"text":"256×256×256"},{"is_correct":false,"key":"C","sort_order":3,"text":"128×128"},{"is_correct":false,"key":"D","sort_order":4,"text":"256×256"}]'::jsonb),
  ('8a021e08-aa5f-a079-a8eb-6330fe91dcaa', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3302', 'section', '數位影像色彩中「R255 G255 B0」呈現何種色彩？', '在RGB色光加法混色中，紅光（R255）與綠光（G255）混合會產生黃光。故選項B正確。', 2, '[{"is_correct":false,"key":"A","sort_order":1,"text":"橙色"},{"is_correct":true,"key":"B","sort_order":2,"text":"黃色"},{"is_correct":false,"key":"C","sort_order":3,"text":"紅色"},{"is_correct":false,"key":"D","sort_order":4,"text":"綠色"}]'::jsonb),
  ('a3f740a6-57f9-0a49-e32a-be8b31d9686f', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3303', 'section', '有關色光RGB混色模式的敘述，下列何者不正確？', 'R255 G0 B255為紅光與藍光混合，呈現洋紅色（紫紅），而非綠色。故選項D錯誤。', 3, '[{"is_correct":false,"key":"A","sort_order":1,"text":"色光三原色是紅（Red）、綠（Green）、藍（Blue）"},{"is_correct":false,"key":"B","sort_order":2,"text":"三原色各分為256個色階，以0～255數值表示"},{"is_correct":false,"key":"C","sort_order":3,"text":"色光混合後明度提高，次數愈多，明度愈高，故稱加法混合、正混合"},{"is_correct":true,"key":"D","sort_order":4,"text":"R0 G0 B0呈現黑色，R255 G0 B255呈現綠色"}]'::jsonb),
  ('e2883242-5852-ff29-e771-cdb96a3998cd', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3304', 'section', '下列有關電腦用色觀念的敘述，何者錯誤？', '電腦列表機輸出使用的是CMYK（青、洋紅、黃、黑）色料減法混合，而非RGB色光。故選項D錯誤。', 4, '[{"is_correct":false,"key":"A","sort_order":1,"text":"目前電腦影像處理的顯色，至少可達16，777，216色，但人眼未必能分辨這麼多色彩"},{"is_correct":false,"key":"B","sort_order":2,"text":"電腦螢幕的色彩是以人類眼睛可辨識的256個色階，可以運算出1，677萬色的色光色彩，這些色彩通稱為全彩"},{"is_correct":false,"key":"C","sort_order":3,"text":"電腦螢幕所呈現的色彩，是以紅（R）、綠（G）、藍（B）色光三原色混合而成"},{"is_correct":true,"key":"D","sort_order":4,"text":"電腦列表機的色彩輸出，是以紅（R）、黃（Y）、綠（G）、藍（B）四種顏色混合而成"}]'::jsonb),
  ('99c61412-5fc8-bc49-d87d-9b75cf471952', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3305', 'section', '影像處理軟體Photoshop的檢色器中，以H：120°、S：100％、B：100％數值表示的色彩，較接近下列何色？', '在HSB色彩模式中，色相（H）120°代表綠色，S100％ B100％為純綠。故選項B正確。', 5, '[{"is_correct":false,"key":"A","sort_order":1,"text":"紅"},{"is_correct":true,"key":"B","sort_order":2,"text":"綠"},{"is_correct":false,"key":"C","sort_order":3,"text":"藍"},{"is_correct":false,"key":"D","sort_order":4,"text":"黃"}]'::jsonb),
  ('9a1f3b2f-655d-5e53-f909-8fa310c20c35', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3306', 'section', '影像處理軟體Photoshop的檢色器中，以H：330°、S：100％、B：100％數值表示的色彩，若對應RGB系統數值，較接近下列何色？', 'H330°為洋紅色，S100％ B100％為純洋紅，對應RGB為紅藍滿載（R255 G0 B255）。故選項C正確。', 6, '[{"is_correct":false,"key":"A","sort_order":1,"text":"R0 G255 B0"},{"is_correct":false,"key":"B","sort_order":2,"text":"R255 G255 B0"},{"is_correct":true,"key":"C","sort_order":3,"text":"R255 G0 B255"},{"is_correct":false,"key":"D","sort_order":4,"text":"R0 G255 B255"}]'::jsonb),
  ('c03629f7-0a04-e0d1-bed1-46120e034668', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3307', 'section', '下列色彩表示法何者最接近鮮紅色？', 'H0° S70％ B80％偏暗紅；5R 4/4彩度低。H0° S100％ B100％才最接近鮮紅，依題意選相對較鮮豔者C。故選項C正確。', 7, '[{"is_correct":false,"key":"A","sort_order":1,"text":"2R-7.5-1S"},{"is_correct":false,"key":"B","sort_order":2,"text":"S 1080-Y10R"},{"is_correct":true,"key":"C","sort_order":3,"text":"H：0°、S：70％、B：80％"},{"is_correct":false,"key":"D","sort_order":4,"text":"5R 4/4"}]'::jsonb),
  ('f808c869-b014-e277-f721-865bbb582d05', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3308', 'section', '為了表示正確的色彩，下列何種方法「無法」達成共識？', '自製顏料色卡缺乏統一科學標準，無法在色彩傳達與管理上達成共識。故選項D正確。', 8, '[{"is_correct":false,"key":"A","sort_order":1,"text":"色彩體系數值表示法"},{"is_correct":false,"key":"B","sort_order":2,"text":"印刷色量數值法"},{"is_correct":false,"key":"C","sort_order":3,"text":"色票"},{"is_correct":true,"key":"D","sort_order":4,"text":"自製顏料色卡"}]'::jsonb),
  ('497fad1d-1c74-cddc-30c8-a754596f6524', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3309', 'section', '色彩的傳達及管理須將色彩依標準規則轉化為共通的表色數值，下列哪一個表色法是不適用、也較不明確的？', '「Red」為一般色名，缺乏精確數值或色票編號，在色彩管理上最不明確。故選項C正確。', 9, '[{"is_correct":false,"key":"A","sort_order":1,"text":"PANTONE 206C"},{"is_correct":false,"key":"B","sort_order":2,"text":"M100＋Y100"},{"is_correct":true,"key":"C","sort_order":3,"text":"Red"},{"is_correct":false,"key":"D","sort_order":4,"text":"Munsell 5R 4/14"}]'::jsonb),
  ('f494c0dc-52c1-35be-dadf-a7afb6fc5c0d', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3310', 'section', '下列何者不是印刷用的油墨色票？', 'ITTEN（伊登）為色彩教學體系，並未發行工業用油墨色票。故選項D正確。', 10, '[{"is_correct":false,"key":"A","sort_order":1,"text":"PANTONE"},{"is_correct":false,"key":"B","sort_order":2,"text":"TOYO"},{"is_correct":false,"key":"C","sort_order":3,"text":"TRUMATCH"},{"is_correct":true,"key":"D","sort_order":4,"text":"ITTEN"}]'::jsonb),
  ('f56433b9-fce2-ad69-71a7-c5c2f019849e', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3311', 'section', 'PANTONE色票表色是依據何種色彩體系製作？', '本題測驗色彩樣本的體系歸屬。PANTONE（彩通）色票是廣泛應用於印刷與設計領域的商業色彩匹配系統。在部分色彩學教材的分類中，PANTONE色票的色彩編排邏輯與發展，被認為是奠基於美國最通用的曼塞爾（Munsell）表色系架構。因此，測驗中通常將其視為依據曼塞爾表色系製作。故選項C正確。', 11, '[{"is_correct":false,"key":"A","sort_order":1,"text":"伊登（Itten）表色系"},{"is_correct":false,"key":"B","sort_order":2,"text":"NCS表色系"},{"is_correct":true,"key":"C","sort_order":3,"text":"曼塞爾（Munsell）表色系"},{"is_correct":false,"key":"D","sort_order":4,"text":"PCCS表色系"}]'::jsonb),
  ('73260299-38ad-1795-ecd5-e6b832d3f434', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3312', 'section', '國際奧委會的五環標準色彩之表示法分別為「Blue：PMS 3005C、Yellow：PMS 137C、Black：PMS 426C、Green：PMS 355C、Red：PMS 192C」，其使用的表色方法為何？', 'PMS代表PANTONE Matching System，為國際通用的印刷油墨色彩編號表示法。故選項A正確。', 12, '[{"is_correct":true,"key":"A","sort_order":1,"text":"印刷油墨色彩編號表示法"},{"is_correct":false,"key":"B","sort_order":2,"text":"印刷色量數值表示法"},{"is_correct":false,"key":"C","sort_order":3,"text":"廣告色料編號表示法"},{"is_correct":false,"key":"D","sort_order":4,"text":"色彩體系數值表示法"}]'::jsonb),
  ('a2d4e476-5b60-33b1-cb47-6cfb233c0087', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3313', 'section', '下列何者不是印刷中所使用的基本原色？', '印刷基本四原色為CMYK（Cyan青， Magenta洋紅， Yellow黃， Black黑）。Blue非原色。故選項B正確。', 13, '[{"is_correct":false,"key":"A","sort_order":1,"text":"Magenta"},{"is_correct":true,"key":"B","sort_order":2,"text":"Blue"},{"is_correct":false,"key":"C","sort_order":3,"text":"Yellow"},{"is_correct":false,"key":"D","sort_order":4,"text":"Cyan"}]'::jsonb),
  ('e9ba61e8-3728-b223-2831-cf841366aff8', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3314', 'section', '國際通用的印刷色量數值中，Y100 C60所呈現之色彩為：', 'Y100（黃）與C60（青）混合，黃色比例較高，會呈現黃綠色。故選項D正確。', 14, '[{"is_correct":false,"key":"A","sort_order":1,"text":"藍色"},{"is_correct":false,"key":"B","sort_order":2,"text":"橙色"},{"is_correct":false,"key":"C","sort_order":3,"text":"洋紅色"},{"is_correct":true,"key":"D","sort_order":4,"text":"黃綠色"}]'::jsonb),
  ('24c11097-01c1-a256-8735-f7f0c4eb5e8a', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3315', 'section', '國際通用的印刷色量數值中，C100 Y60接近何種顏色？', 'C100（青）與Y60（黃）混合，青色比例較高，會呈現碧綠色（偏青的綠）。故選項C正確。', 15, '[{"is_correct":false,"key":"A","sort_order":1,"text":"紫青色"},{"is_correct":false,"key":"B","sort_order":2,"text":"天藍色"},{"is_correct":true,"key":"C","sort_order":3,"text":"碧綠色"},{"is_correct":false,"key":"D","sort_order":4,"text":"灰綠色"}]'::jsonb),
  ('72a60bdf-0029-356d-a350-d53d3cbd5e56', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3316', 'section', '國際通用的印刷色量數值中，M80 C60 K60接近何種色彩？', 'M80（洋紅）與C60（青）混合呈紫色，加入K60（黑）後明度降低，呈現深紫色。故選項A正確。', 16, '[{"is_correct":true,"key":"A","sort_order":1,"text":"深紫色"},{"is_correct":false,"key":"B","sort_order":2,"text":"淺紫色"},{"is_correct":false,"key":"C","sort_order":3,"text":"深綠色"},{"is_correct":false,"key":"D","sort_order":4,"text":"淺綠色"}]'::jsonb),
  ('aa182544-b05a-9d4a-ece9-b9482d6ee805', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3317', 'section', '彩色印刷四原色無法呈現下列何種色彩？', '銀色、金色等金屬色屬於特別色，無法單純用CMYK四色油墨疊印精準呈現。故選項C正確。', 17, '[{"is_correct":false,"key":"A","sort_order":1,"text":"暗藍色"},{"is_correct":false,"key":"B","sort_order":2,"text":"紅紫色"},{"is_correct":true,"key":"C","sort_order":3,"text":"銀色"},{"is_correct":false,"key":"D","sort_order":4,"text":"粉紫色"}]'::jsonb),
  ('9a47590d-b0b7-b52a-4d8f-7025b78cf11d', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3318', 'section', '中國陰陽五行學說中，中國人所謂的大紅色——「朱」色較接近下列何種色彩？', '中國傳統的大紅色（朱）非常鮮豔，最接近洋紅與黃色滿載的M100 Y100。故選項B正確。', 18, '[{"is_correct":false,"key":"A","sort_order":1,"text":"M100"},{"is_correct":true,"key":"B","sort_order":2,"text":"M100Y100"},{"is_correct":false,"key":"C","sort_order":3,"text":"Y100"},{"is_correct":false,"key":"D","sort_order":4,"text":"M100C100"}]'::jsonb),
  ('54383ccf-2168-7387-4b84-c4fe99ee7611', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3319', 'section', '對於彩色四色印刷的描述，下列何者錯誤？', 'C版（青）與Y版（黃）套印會呈現綠色，而非紅紫色。故選項B錯誤。', 19, '[{"is_correct":false,"key":"A","sort_order":1,"text":"屬於色彩並置混合的類型"},{"is_correct":true,"key":"B","sort_order":2,"text":"分色後的C版與Y版套印後會呈現紅紫色"},{"is_correct":false,"key":"C","sort_order":3,"text":"C90 Y90是鮮豔的綠色"},{"is_correct":false,"key":"D","sort_order":4,"text":"可另外製版套印金色或銀色等特別色"}]'::jsonb),
  ('205e11b9-2380-d784-9ac6-169b8070bc58', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3320', 'section', '由電腦製作的色彩樣本在印刷或輸出後常發生色彩偏差的情況，已成為設計師常見的困擾。下列哪一種油墨色票，是由電腦直接列印，能呈現所謂「所見即所得」的效果？', 'FOCOLTONE色票系統專為數位排版設計，能提供精準的數位轉印刷演色效果。故選項D正確。', 20, '[{"is_correct":false,"key":"A","sort_order":1,"text":"TOYO"},{"is_correct":false,"key":"B","sort_order":2,"text":"DIC"},{"is_correct":false,"key":"C","sort_order":3,"text":"PANTONE"},{"is_correct":true,"key":"D","sort_order":4,"text":"FOCOLTONE"}]'::jsonb),
  ('69420018-3d42-726c-be6f-d3fe956f5646', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3321', 'section', '對於色票的製作依據之敘述，下列何者不正確？', 'TOYO色票並非依據PCCS製作，且Colorcurve是依據CIELAB製作。故選項C敘述錯誤。', 21, '[{"is_correct":false,"key":"A","sort_order":1,"text":"PANTONE色票依據曼塞爾表色系製作"},{"is_correct":false,"key":"B","sort_order":2,"text":"Colorcurve色票依據CIELAB表色系製作"},{"is_correct":true,"key":"C","sort_order":3,"text":"TOYO色票依據PCCS表色系製作"},{"is_correct":false,"key":"D","sort_order":4,"text":"PCCS色票依據PCCS表色系製作"}]'::jsonb),
  ('5ae87e35-1fb3-93de-3fc1-271fc9614f20', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3322', 'section', '下列有關色票的敘述，何者不正確？', 'PANTONE色票是由美國PANTONE公司發行，並非美國光學學會（OSA）。故選項A錯誤。', 22, '[{"is_correct":true,"key":"A","sort_order":1,"text":"PANTONE色票是美國光學學會（OSA）發行，廣泛使用在織品與印刷領域"},{"is_correct":false,"key":"B","sort_order":2,"text":"NCS表色系是瑞典國家工業規格的表色法"},{"is_correct":false,"key":"C","sort_order":3,"text":"曼塞爾（Munsell）表色系為我國、日本、美國工業規格採用的表色法"},{"is_correct":false,"key":"D","sort_order":4,"text":"DIC色票為日本顏料公司所出版"}]'::jsonb),
  ('76e401d2-3f26-f36f-eb99-f86adae303e6', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', 'QB3323', 'section', '關於各國色票（色樣本）的配對，下列何者錯誤？', '美國常用PANTONE與FOCOLTONE，FOCOLTONE起源於英國但廣泛使用。A選項配對錯誤。故選項A錯誤。', 23, '[{"is_correct":true,"key":"A","sort_order":1,"text":"美國：PANTONE、FOCOLTONE、Colorcurve色票"},{"is_correct":false,"key":"B","sort_order":2,"text":"德國：DIN、RAL色票"},{"is_correct":false,"key":"C","sort_order":3,"text":"日本：PCCS、DIC、TOYO色票"},{"is_correct":false,"key":"D","sort_order":4,"text":"中華民國：中華色彩研究所色票"}]'::jsonb),
  ('f8b63ee9-8f06-c664-7d13-6cf2469955f7', 'd5e935ef-35e9-199f-2131-ad2d9957cce4', 'QB4101', 'section', '關於人類視覺對光與色彩訊息的處理過程，下列由左至右的順序，何者正確？', '光線進入眼球順序：角膜→瞳孔→水晶體→玻璃體→視網膜→視神經→大腦。故選項B正確。', 1, '[{"is_correct":false,"key":"A","sort_order":1,"text":"光源一角膜一瞳孔一玻璃體一水晶體一視網膜一視神經一大腦一色彩感覺產生"},{"is_correct":true,"key":"B","sort_order":2,"text":"光源一角膜一瞳孔一水晶體一玻璃體一視網膜一視神經一大腦一色彩感覺產生"},{"is_correct":false,"key":"C","sort_order":3,"text":"光源一瞳孔一角膜一玻璃體一水晶體一視神經一大腦一視網膜一色彩感覺產生"},{"is_correct":false,"key":"D","sort_order":4,"text":"光源一瞳孔一角膜一水晶體一玻璃體一視神經一大腦一視網膜一色彩感覺產生"}]'::jsonb),
  ('01a96646-281c-818d-e43b-ff2b43ffcfa0', 'd5e935ef-35e9-199f-2131-ad2d9957cce4', 'QB4102', 'section', '眼球中，控制光線進出眼球多寡的部位稱為？', '虹膜負責控制瞳孔的大小，進而調節進入眼球的光線多寡。故選項C正確。', 2, '[{"is_correct":false,"key":"A","sort_order":1,"text":"角膜"},{"is_correct":false,"key":"B","sort_order":2,"text":"水晶體"},{"is_correct":true,"key":"C","sort_order":3,"text":"虹膜"},{"is_correct":false,"key":"D","sort_order":4,"text":"玻璃體"}]'::jsonb),
  ('b3817c55-76be-cbad-810b-577d1049e252', 'd5e935ef-35e9-199f-2131-ad2d9957cce4', 'QB4103', 'section', '眼球中負責聚集光線、調節焦距的是：', '水晶體具有彈性，負責聚集光線並調節焦距，使影像清晰成像於視網膜。故選項A正確。', 3, '[{"is_correct":true,"key":"A","sort_order":1,"text":"水晶體"},{"is_correct":false,"key":"B","sort_order":2,"text":"虹膜"},{"is_correct":false,"key":"C","sort_order":3,"text":"玻璃體"},{"is_correct":false,"key":"D","sort_order":4,"text":"錐狀細胞"}]'::jsonb),
  ('e7f24473-8a01-4626-8e79-f05b1f055106', 'd5e935ef-35e9-199f-2131-ad2d9957cce4', 'QB4104', 'section', '人類眼球中的視網膜上具有兩種視覺感應細胞是？', '視網膜上具有兩種主要的視覺感應細胞：柱狀細胞與錐狀細胞。故選項A正確。', 4, '[{"is_correct":true,"key":"A","sort_order":1,"text":"柱狀與錐狀細胞"},{"is_correct":false,"key":"B","sort_order":2,"text":"圓狀與片狀細胞"},{"is_correct":false,"key":"C","sort_order":3,"text":"鞏膜與脈絡膜細胞"},{"is_correct":false,"key":"D","sort_order":4,"text":"盲點與中心窩細胞"}]'::jsonb),
  ('97147e89-e7aa-7188-fb71-60da1ba32e45', 'd5e935ef-35e9-199f-2131-ad2d9957cce4', 'QB4105', 'section', '眼球中負責分辨色彩的是：', '錐狀細胞主要負責感應色彩與強光下的視覺細節。故選項D正確。', 5, '[{"is_correct":false,"key":"A","sort_order":1,"text":"虹膜"},{"is_correct":false,"key":"B","sort_order":2,"text":"水晶體"},{"is_correct":false,"key":"C","sort_order":3,"text":"桿狀細胞"},{"is_correct":true,"key":"D","sort_order":4,"text":"錐狀細胞"}]'::jsonb),
  ('d5f5eb66-eb89-7b25-13a2-7565d4332f63', 'd5e935ef-35e9-199f-2131-ad2d9957cce4', 'QB4106', 'section', '錐狀細胞在眼球那個部位分布最為集中？', '錐狀細胞在視網膜的中心窩分布最為密集，提供最清晰的色彩視覺。故選項B正確。', 6, '[{"is_correct":false,"key":"A","sort_order":1,"text":"水晶體"},{"is_correct":true,"key":"B","sort_order":2,"text":"中心窩"},{"is_correct":false,"key":"C","sort_order":3,"text":"盲點"},{"is_correct":false,"key":"D","sort_order":4,"text":"神經束"}]'::jsonb),
  ('329ce331-2d30-74e9-59a8-2e9f388acb85', 'd5e935ef-35e9-199f-2131-ad2d9957cce4', 'QB4107', 'section', '視網膜中的柱狀細胞是感應光線的：', '柱狀細胞對光線明暗非常敏感，負責弱光下的視覺，無法分辨色彩。故選項A正確。', 7, '[{"is_correct":true,"key":"A","sort_order":1,"text":"明暗"},{"is_correct":false,"key":"B","sort_order":2,"text":"密度"},{"is_correct":false,"key":"C","sort_order":3,"text":"色相"},{"is_correct":false,"key":"D","sort_order":4,"text":"彩度"}]'::jsonb),
  ('87a67699-c8d1-9d30-1470-5ec239642c04', 'd5e935ef-35e9-199f-2131-ad2d9957cce4', 'QB4108', 'section', '有關視網膜上柱狀細胞的構成與作用，下列敘述何者正確？', '柱狀細胞數量遠多於錐狀細胞，且主要分布在視網膜的周圍區域。故選項B正確。', 8, '[{"is_correct":false,"key":"A","sort_order":1,"text":"數量較錐狀細胞少"},{"is_correct":true,"key":"B","sort_order":2,"text":"平均分布在視網膜上"},{"is_correct":false,"key":"C","sort_order":3,"text":"光線愈亮，感應力愈強"},{"is_correct":false,"key":"D","sort_order":4,"text":"負責感應色彩的色相"}]'::jsonb),
  ('52ddba85-2f28-6d06-a4a7-cb36d36d2ba7', 'd5e935ef-35e9-199f-2131-ad2d9957cce4', 'QB4109', 'section', '下列關於錐、柱狀細胞的敘述，何者不正確？', '柱狀細胞的反應速度實際上比錐狀細胞慢。故選項C錯誤。', 9, '[{"is_correct":false,"key":"A","sort_order":1,"text":"錐狀細胞主要分布在中心窩附近"},{"is_correct":false,"key":"B","sort_order":2,"text":"柱狀細胞對光線明暗的反應非常敏感"},{"is_correct":true,"key":"C","sort_order":3,"text":"柱狀細胞的反應速度比錐狀細胞慢"},{"is_correct":false,"key":"D","sort_order":4,"text":"某些頭部受到創傷的人，會對色彩失去知覺，主要是錐狀細胞受創所致"}]'::jsonb),
  ('e2d7f771-9117-0cb5-24cd-53d03fca7a88', '4caa3fe7-0962-e35d-5c8a-e517e0479171', 'QB4201', 'section', '一個顏色受到其他顏色的影響而產生變化之情形稱為？', '本單元探討色彩的對比性，核心觀念在於相鄰或相續的顏色彼此互動，使人對色彩的判斷或感覺產生偏移的錯覺現象。色彩對比依觀看方式可分為同時對比與繼續對比，並包含色相對比、明度對比、彩度對比及面積對比等類型。當不同色彩並列時，常在交界處產生更明顯的邊緣對比，或因視覺生理的補色殘像而影響色彩的鮮豔度與明暗感。', 1, '[{"is_correct":false,"key":"A","sort_order":1,"text":"色彩反覆"},{"is_correct":false,"key":"B","sort_order":2,"text":"色彩調和"},{"is_correct":false,"key":"C","sort_order":3,"text":"色彩恆常"},{"is_correct":true,"key":"D","sort_order":4,"text":"色彩對比"}]'::jsonb),
  ('92e6ed25-854f-07dc-d60a-b77450aa1a15', '7330aaf4-ae55-462e-11f3-bfff61572060', 'QB4301', 'section', '色彩會令人感到溫暖或寒冷，是因為：', '本單元探討色彩的感覺與心理，核心觀念在於色彩引起的心理感覺與情感反應。色彩意象與感覺是由色彩引起的心理反應，包含聯想、象徵、好惡以及寒暖、輕重、軟硬、興奮與沉靜等複雜變化。研究指出，暖色調（如紅、橙、黃）通常能帶來活力、溫暖與刺激食慾的感官，而冷色調（如藍、綠）則能營造平靜、冷靜與安定的氛圍，人們對顏色的心理感受也會受到個人經驗、性別與文化背景的影響。', 1, '[{"is_correct":false,"key":"A","sort_order":1,"text":"生理的刺激"},{"is_correct":false,"key":"B","sort_order":2,"text":"個人的喜好不同"},{"is_correct":true,"key":"C","sort_order":3,"text":"心理的反應"},{"is_correct":false,"key":"D","sort_order":4,"text":"光線的影響"}]'::jsonb),
  ('d23db196-2079-af53-5f41-82903797421c', '6ec39331-f103-dd3b-b13c-fbd54a4ca053', 'QB4401', 'section', '當我們遠望窗外同距離的海報或廣告時，有些色彩看得很清楚，有些則顯得模糊，這種現象可稱為？', '本單元探討色彩的明視度與注目性，核心觀念在於色彩在視覺傳達與引人注意的心理感受。明視度是指圖形或文字與背景在色彩搭配上的可見度、辨識度，主要受兩者間的明度差影響，明度差越大明視度越高；注目性（誘目性）則是色彩容易引起注意的程度，通常高明度、高彩度及暖色系的前進色具有較高的注目性，常用於海報與標誌設計以達到引人注目的效果。', 1, '[{"is_correct":false,"key":"A","sort_order":1,"text":"薄暮現象"},{"is_correct":false,"key":"B","sort_order":2,"text":"色散現象"},{"is_correct":false,"key":"C","sort_order":3,"text":"色滲效果"},{"is_correct":true,"key":"D","sort_order":4,"text":"色彩明視度"}]'::jsonb),
  ('fdc13455-e40d-a02b-697a-f68535e14007', '982acbb9-337d-69a9-043e-81cd82267b5b', 'QB5101', 'section', '人們看到蘋果感受到紅色、暖色、美味等共感覺，之後這些感覺傳達到大腦記憶區產生「甜美、蘋果派、高科技等個人好惡與意象」，後段敘述之階段稱為？', '本單元探討色彩嗜好，核心觀念在於個體或群體對色彩的喜好傾向。研究顯示，色彩嗜好並非固定不變，而是受到年齡、性別、文化、民族、地域風土、生活經驗以及流行趨勢等多重生理與心理因素的動態影響，並與色彩所帶來的心理效應和意象聯想密切相關。', 1, '[{"is_correct":false,"key":"A","sort_order":1,"text":"色彩恆常（Color Constancy）"},{"is_correct":true,"key":"B","sort_order":2,"text":"色彩認知（Color Cognition）"},{"is_correct":false,"key":"C","sort_order":3,"text":"色彩適應（Color Adaptation）"},{"is_correct":false,"key":"D","sort_order":4,"text":"色彩感知（Color Sensation）"}]'::jsonb),
  ('c8f6f3ec-ccce-45a6-a2bd-483d17d491fc', 'b4af36a7-0ad8-93a2-06fd-d228125ad813', 'QB5201', 'section', '具有熱情、興奮、危險等意象的色彩是？', '本單元探討色彩呈現中的色彩聯想。核心觀念在於色彩引發的心理感知與具體或抽象事物的心理連結。色彩聯想是基於人類對大自然與生活經驗的累積（如藍色聯想到天空、綠色聯想到草地與和平），進而轉化為共通的心理規範。研究顯示，橙色系、紅色系及無彩色最容易讓受測者產生聯想，且色彩聯想會受到情境、文化、性別等因素影響，是品牌設計與視覺傳達中建立情感共鳴與記憶點的重要基礎。', 1, '[{"is_correct":true,"key":"A","sort_order":1,"text":"紅色"},{"is_correct":false,"key":"B","sort_order":2,"text":"黃色"},{"is_correct":false,"key":"C","sort_order":3,"text":"藍色"},{"is_correct":false,"key":"D","sort_order":4,"text":"綠色"}]'::jsonb),
  ('a3fa6cc6-5b95-091e-f7d1-470d23871474', 'f290f7f6-c52e-3596-af5d-dbe7a39e3000', 'QB5301', 'section', '影響四季彩色感覺最主要的因素是？', '本單元探討色彩認知，核心觀念在於自然環境對色彩感覺的影響。人類對於四季（春、夏、秋、冬）的色彩感覺，最主要源自於對「自然環境」變化的長期觀察與體驗。例如春天萬物復甦的新綠、夏天海洋的藍色、秋天落葉的橙黃色、冬天冰雪的白色等。這些基於自然景觀變化的色彩聯想，是形成四季色彩感覺最直接且主要的因素。', 1, '[{"is_correct":false,"key":"A","sort_order":1,"text":"文化習俗"},{"is_correct":false,"key":"B","sort_order":2,"text":"資訊通訊"},{"is_correct":true,"key":"C","sort_order":3,"text":"自然環境"},{"is_correct":false,"key":"D","sort_order":4,"text":"人文素養"}]'::jsonb),
  ('46462b5f-ef96-6793-4df7-4c637a96e456', '0239f7f4-cac4-6419-4a7e-2afb7664f2ec', 'QB6101', 'section', '主張「任何色彩皆由黑與白、明與暗所組成，色彩明度白量與黑量比值，若以2：3或3：4的比例配色就可以產生調和感」的學者是？', '本單元探討配色調和與色彩應用，核心觀念在於掌握色彩的搭配原則與調和理論。常見的配色法包含單色、類似色、互補色及多色相配色等，並可依據賈德、伊登等學者的秩序與對比原理，透過適當調整色相、明度、彩度及面積比例，在變化中求取統一，以達到畫面協調與平衡的視覺效果。', 1, '[{"is_correct":true,"key":"A","sort_order":1,"text":"亞里斯多德（Aristotle）"},{"is_correct":false,"key":"B","sort_order":2,"text":"曼塞爾（Munsell）"},{"is_correct":false,"key":"C","sort_order":3,"text":"歌德（Goethe）"},{"is_correct":false,"key":"D","sort_order":4,"text":"貝哲德（Bezold）"}]'::jsonb),
  ('78b37d5b-8a4a-0053-2cde-6febbc89d55e', 'f88cfc0f-8698-8311-3af6-05bce6d46188', 'QB6201', 'section', '兩種或是兩種以上的色彩並置一起時，其上下、左右之色彩的重量感相等，稱為：', '本單元探討形式原理與色彩應用，核心觀念在於將美的形式原理（如對稱、均衡、對比、比例、調和、律動、統一等）結合色彩配置。透過相同或相似形色的規律重複、對立色彩的並列，或是色相明度彩度的漸層變化，能創造出具視覺層次與節奏感的畫面，達到整體視覺的和諧與設計訴求。', 1, '[{"is_correct":false,"key":"A","sort_order":1,"text":"漸層"},{"is_correct":false,"key":"B","sort_order":2,"text":"律動"},{"is_correct":false,"key":"C","sort_order":3,"text":"強調"},{"is_correct":true,"key":"D","sort_order":4,"text":"均衡"}]'::jsonb),
  ('7645d433-ce11-a789-e58d-804433e774f9', '178f3050-304f-7a46-ca5f-6c01d7a47a5e', 'QB6301', 'section', '考慮到消費者的色彩意象及嗜好，並配合市場色彩的機能或流行性，這種選擇色彩的方法稱為？', '本單元探討色彩在設計上的應用，核心觀念在於將色彩學原理落實於視覺傳達與實務設計中。設計師須依據產品定位與目標大眾，整合固有色、環境色與光源的影響，並靈活運用色相、明度、彩度等色彩三要素及色彩心理效應，以建立具識別性的品牌形象，引導使用者視覺焦點，創造兼具美感與實用性的設計作品。', 1, '[{"is_correct":false,"key":"A","sort_order":1,"text":"色彩對比"},{"is_correct":false,"key":"B","sort_order":2,"text":"色彩配置"},{"is_correct":false,"key":"C","sort_order":3,"text":"色彩調和"},{"is_correct":true,"key":"D","sort_order":4,"text":"色彩計劃"}]'::jsonb),
  ('5ee23918-c6de-3200-df69-bd64574d7c5b', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3001', 'chapter', '以中明度的灰色與純紅色之廣告顏料各半混合之後，所形成的顏色，較接近下列何種色調（Tone）？', '純色加入中明度灰會形成濁色調（dull tone）。粉色調是加白，暗色調加黑，深色調加少量黑。故選項C正確。', 1, '[{"is_correct":false,"key":"A","sort_order":1,"text":"粉（淡）色調（Pale tone，p）"},{"is_correct":false,"key":"B","sort_order":2,"text":"暗色調（Dark tone，dk）"},{"is_correct":true,"key":"C","sort_order":3,"text":"鈍（濁）色調（Dull tone，d）"},{"is_correct":false,"key":"D","sort_order":4,"text":"深色調（Deep tone，dp）"}]'::jsonb),
  ('afda5e7d-62eb-25a5-1d28-7daf870e948a', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3002', 'chapter', '以曼塞爾（Munsell）表色法表示之三色，甲色7R 6/5，乙色5BG 4/6，丙色6Y 8/4，下列有關之敘述何者正確？', '甲明度6，丙明度8最高；甲為暖色，乙為寒色；乙彩度6最高；丙為有彩色。故選項C正確。', 2, '[{"is_correct":false,"key":"A","sort_order":1,"text":"明度最高者為甲"},{"is_correct":false,"key":"B","sort_order":2,"text":"甲乙色均為寒色"},{"is_correct":true,"key":"C","sort_order":3,"text":"彩度最高者為乙"},{"is_correct":false,"key":"D","sort_order":4,"text":"丙色為無彩色"}]'::jsonb),
  ('81740316-8c6e-3afd-eaad-862a00ca6086', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3003', 'chapter', '下列關於日本色彩研究所表色系（PCCS）的敘述，何者不正確？', 'PCCS色相環以24色為主；表色法順序應為色相-明度-彩度（2R-4.5-9S）。故選項C不正確。', 3, '[{"is_correct":false,"key":"A","sort_order":1,"text":"色相環以紅、橙、黃、綠、藍、紫六色相為主"},{"is_correct":false,"key":"B","sort_order":2,"text":"最大的特徵是加入色調（Tone），將明度高低和彩度強弱一併考慮"},{"is_correct":true,"key":"C","sort_order":3,"text":"某一紅色的表色法為9S-4.5-2R"},{"is_correct":false,"key":"D","sort_order":4,"text":"補色沒有在色相環的直徑兩端"}]'::jsonb),
  ('4f153567-ffd6-1ead-0e57-fd9bd03c30ad', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3004', 'chapter', '曼塞爾（Munsell）表色體系的明度階段，從純白（含）到純黑（含）共分為幾個階段？', '曼塞爾明度階段從N0（純黑）至N10（純白），共分為11個階段。故選項C正確。', 4, '[{"is_correct":false,"key":"A","sort_order":1,"text":"9"},{"is_correct":false,"key":"B","sort_order":2,"text":"10"},{"is_correct":true,"key":"C","sort_order":3,"text":"11"},{"is_correct":false,"key":"D","sort_order":4,"text":"12"}]'::jsonb),
  ('8ceabd7e-d081-cfe7-5766-0c8aab60398c', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3005', 'chapter', '關於瑞典的自然表色系（Natural Color System，簡稱NCS）特性敘述，以下何者錯誤？', 'NCS以紅黃綠藍黑白為基本色，採用紅黃、綠藍、黑白為座標軸。選項B敘述錯誤，應為紅綠、黃藍。', 5, '[{"is_correct":false,"key":"A","sort_order":1,"text":"以德國生理學家赫林（E. Hering）的四原色理論為基礎"},{"is_correct":true,"key":"B","sort_order":2,"text":"採用紅－黃、綠－藍、黑－白等三組色彩為色立體的三個座標軸"},{"is_correct":false,"key":"C","sort_order":3,"text":"標色法為黑量、彩色量、色相彩色量百分比"},{"is_correct":false,"key":"D","sort_order":4,"text":"係歐洲設計界通用的表色法"}]'::jsonb),
  ('58b3cfb3-26c2-5b30-120f-df86693c4c0c', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3006', 'chapter', '以下所列舉的四種表色系中，何者採用色調（Tone）的概念設計而成？', 'PCCS表色系最大的特徵是加入色調（Tone）概念，將明度與彩度合併評估。故選項B正確。', 6, '[{"is_correct":false,"key":"A","sort_order":1,"text":"國際照明委員會（International Commission of Illumination）的CIE表色系"},{"is_correct":true,"key":"B","sort_order":2,"text":"美國色彩協議會暨國家標準局（ISCC-NBS）表色系"},{"is_correct":false,"key":"C","sort_order":3,"text":"奧斯華德表色系（Ostwald Color System）"},{"is_correct":false,"key":"D","sort_order":4,"text":"曼塞爾表色系（Munsell Color System）"}]'::jsonb),
  ('5f77c077-f5ad-b284-da36-acca18827e5b', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3007', 'chapter', '以下有關色彩命名的說明，何者錯誤？', '「薰衣草紫」為西方傳統色名，並非中國傳統色名。故選項A錯誤。', 7, '[{"is_correct":true,"key":"A","sort_order":1,"text":"「薰衣草紫」（Lavender）是中國傳統色名"},{"is_correct":false,"key":"B","sort_order":2,"text":"引用植物名稱作為色彩名，屬於固有色名，例如：柳綠"},{"is_correct":false,"key":"C","sort_order":3,"text":"「紫紅」意為帶紫的紅色，屬於系統色名"},{"is_correct":false,"key":"D","sort_order":4,"text":"慣用色名大多引用自生活上較常見或常用的物體名稱"}]'::jsonb),
  ('e0042e56-618b-90e0-4fec-d0f1ed9cc97b', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3008', 'chapter', 'PCCS表色體系的「色相面」常以曲線形表示，而非以一般人所熟識的面之概念形（矩形）表示。若進一步比對兩者，可發現「色相面」比矩形少了斜線部分，下列何者是該色相面缺少斜線部分的主要原因？', 'PCCS色相面呈曲線，是因排列成弧線形能使色彩跳階平順，符合人類視知覺感受。故選項D正確。', 8, '[{"is_correct":false,"key":"A","sort_order":1,"text":"將色相面繪製成曲線形，在造形上較具美感"},{"is_correct":false,"key":"B","sort_order":2,"text":"製成色立體時，每一個色相面的觸覺滑順，不易刮傷皮膚"},{"is_correct":false,"key":"C","sort_order":3,"text":"排列形成弧線形，易使色彩的跳階平順，合於人類的視知覺感受"},{"is_correct":true,"key":"D","sort_order":4,"text":"不可能有色彩存在於斜線部分，故將它捨棄"}]'::jsonb),
  ('f9455f61-6762-ded3-fe33-666c8415d610', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3009', 'chapter', '下列何者是理想白（擴散反射率100％，即色光做全部反射的白）？', '理想白在曼塞爾體系為N10，奧斯華德為a。選項C曼塞爾N10為正確答案。', 9, '[{"is_correct":false,"key":"A","sort_order":1,"text":"奧斯華德（Ostwald）的a"},{"is_correct":false,"key":"B","sort_order":2,"text":"奧斯華德（Ostwald）的p"},{"is_correct":true,"key":"C","sort_order":3,"text":"曼塞爾（Munsell）的N10"},{"is_correct":false,"key":"D","sort_order":4,"text":"PCCS的W9.5"}]'::jsonb),
  ('263513ac-a090-6504-0431-ce7a8c01ea6c', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3010', 'chapter', '關於色料彩度高、低的敘述，下列何者正確？', '同一色彩，小面積時彩度感覺較低，大面積時彩度感覺較高，此為面積效應。故選項B正確。', 10, '[{"is_correct":false,"key":"A","sort_order":1,"text":"純色混合無彩色，則彩度提高"},{"is_correct":true,"key":"B","sort_order":2,"text":"同一色彩，小面積色票的彩度感覺，較大面積的彩度低"},{"is_correct":false,"key":"C","sort_order":3,"text":"兩互補色彩相混合，則彩度提高"},{"is_correct":false,"key":"D","sort_order":4,"text":"同一色票，由於人眼視覺機制的影響，所以近看時彩度比遠看時低"}]'::jsonb),
  ('b8244a4c-d2d5-a161-b61b-fc238e0f95b0', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3011', 'chapter', '有關國內常用的色票與色彩系統的對應關係，下列何者敘述錯誤？', 'DIC色票是依據曼塞爾及PCCS等實用體系製作，並非依據NCS。故選項A錯誤。', 11, '[{"is_correct":true,"key":"A","sort_order":1,"text":"大日本顏料及化學公司的DIC色票，是依據NCS表色系製作的"},{"is_correct":false,"key":"B","sort_order":2,"text":"中華色彩研究所的71a色票，其所依據的色彩系統和PCCS表色系相似"},{"is_correct":false,"key":"C","sort_order":3,"text":"美國PANTONE公司的PANTONE色票，是依據曼塞爾（Munsell）表色系製作的"},{"is_correct":false,"key":"D","sort_order":4,"text":"日本色研事業株式會社的129a、129b配色卡，是依據PCCS表色系製作的"}]'::jsonb),
  ('42e85801-77bf-1d56-8ecd-66744f7437c3', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3012', 'chapter', '下列各表色法常用記號的敘述，何者正確？', 'PCCS表色法H-V-C中，C代表彩度（Chroma）；2R-4.5-9S中，S代表Saturation（彩度）。故選項C正確。', 12, '[{"is_correct":false,"key":"A","sort_order":1,"text":"PCCS表色系中，H－V－C的C，即為color"},{"is_correct":false,"key":"B","sort_order":2,"text":"曼塞爾（Munsell）表色系中，明度N0的N，即為number"},{"is_correct":true,"key":"C","sort_order":3,"text":"PCCS表色系中，2R－4.5－9S的S，即為Saturation"},{"is_correct":false,"key":"D","sort_order":4,"text":"PCCS表色系中，H－V－C的V，即為vivid"}]'::jsonb),
  ('e2e55324-ae4a-2a73-cee2-89dfb5ea866f', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3013', 'chapter', '有關「色調」（tone）的敘述，下列何者錯誤？', 'PCCS體系中有彩色共分為12個色調，而非10個。故選項C錯誤。', 13, '[{"is_correct":false,"key":"A","sort_order":1,"text":"PCCS體系最具代表性的概念"},{"is_correct":false,"key":"B","sort_order":2,"text":"將明度高低和彩度強弱合併為一，而保留色相之別的分類法"},{"is_correct":true,"key":"C","sort_order":3,"text":"有彩色分共10個色調"},{"is_correct":false,"key":"D","sort_order":4,"text":"dp色調的彩度與b色調的彩度相同"}]'::jsonb),
  ('6479c835-08a9-c39a-29b1-e34150fad3a0', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3014', 'chapter', '下列有關伊登（Itten）表色系的敘述，何者正確？', '伊登色相環依據光譜順序，將6對補色分別置於直徑兩端的位置上。故選項B正確。', 14, '[{"is_correct":false,"key":"A","sort_order":1,"text":"伊登十二色相環的繪製，先於中間三角形中塗上三原色，黃色在頂端、紅色在左下、藍色在右下"},{"is_correct":true,"key":"B","sort_order":2,"text":"其色相環依據日光光譜順序，將6對補色分別置於直徑兩端的位置上"},{"is_correct":false,"key":"C","sort_order":3,"text":"由上方鳥瞰伊登色立體展開圖形（星狀圖），可看出其彩度共分7階段"},{"is_correct":false,"key":"D","sort_order":4,"text":"色相環中的第一次色會與第三次色形成互補狀態，並位於直徑兩端"}]'::jsonb),
  ('491c917c-6f43-8b31-1cb1-447ada2c5e5e', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3015', 'chapter', '有關CIE表色系統的敘述，下列何者錯誤？', 'CIE為最具科學化表色系，但數值抽象，不適合直接用於一般繪畫選色。故選項D錯誤。', 15, '[{"is_correct":false,"key":"A","sort_order":1,"text":"CIE表色系屬於混色系"},{"is_correct":false,"key":"B","sort_order":2,"text":"以色光三原色紅（R）、綠（G）、藍（B）三色為準，設定X、Y、Z的刺激值"},{"is_correct":false,"key":"C","sort_order":3,"text":"訂有A、B、C三種標準光源，其色溫分別為2856K、4874K、6774K"},{"is_correct":true,"key":"D","sort_order":4,"text":"是目前最具科學化的表色系統，適合直接運用於一般繪畫時顏色之選用"}]'::jsonb),
  ('87913db5-ace8-f5da-5ad0-fdbc90c9c6c3', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3016', 'chapter', '下列何者在等色相面上，其分布位置錯誤？', '濁色分布於等色相面內部靠近無彩色軸，明色與暗色才分布於外圍邊緣。故選項C錯誤。', 16, '[{"is_correct":false,"key":"A","sort_order":1,"text":"暗色分布於等色相面外圍邊緣區域，並靠近下方"},{"is_correct":false,"key":"B","sort_order":2,"text":"明色分布於等色相面外圍邊緣區域，並靠近上方"},{"is_correct":true,"key":"C","sort_order":3,"text":"濁色分布於等色相面外圍邊緣區域，並靠近上方或下方"},{"is_correct":false,"key":"D","sort_order":4,"text":"純色分布於等色相面外圍邊緣區域，距離明度軸最遠的地方"}]'::jsonb),
  ('9639fe67-4a01-cf93-4a0c-8c87901efd44', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3017', 'chapter', '有關曼塞爾（Munsell）表色體系之色立體（Color Solid）觀念，下列敘述何者正確？', '曼塞爾色立體以明度為垂直軸，彩度為水平軸，構成等色相面。故選項A正確。', 17, '[{"is_correct":true,"key":"A","sort_order":1,"text":"是以色彩三要素（色相、明度、彩度）有系統組合，所建構的立體色彩座標空間"},{"is_correct":false,"key":"B","sort_order":2,"text":"各色相均以明度階段為橫軸，彩度階段為縱軸，構成「等色相面」"},{"is_correct":false,"key":"C","sort_order":3,"text":"以明度階段為色立體的中心軸並賦予座標數值，數值越大者表示明度越低，反之則越高"},{"is_correct":false,"key":"D","sort_order":4,"text":"各等色相面上，均以彩度階段為橫軸，賦予座標數值表示色彩的鮮濁程度；數值最大者為純色，且各等色相面之純色彩度值均相同"}]'::jsonb),
  ('994d74cc-69a5-ae48-e90f-bd780aaa1edf', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3018', 'chapter', '以曼塞爾（Munsell）表色法表示之三色，甲色5R 8/6，乙色5Y 6/4，丙色5G 7/8，下列敘述何者正確？', '甲明度8最高；甲為暖色，丙為寒色；丙彩度8最高；乙為有彩色。故選項B正確。', 18, '[{"is_correct":false,"key":"A","sort_order":1,"text":"甲乙均為寒色"},{"is_correct":true,"key":"B","sort_order":2,"text":"明度最高為甲色"},{"is_correct":false,"key":"C","sort_order":3,"text":"彩度最高為乙色"},{"is_correct":false,"key":"D","sort_order":4,"text":"丙色為無彩色"}]'::jsonb),
  ('b222966b-9a18-e358-2ca2-c7f50e66f7f9', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3019', 'chapter', '下列有關CIE體系之敘述，何者錯誤？', 'CIE體系中，Y代表明度與反射率，彩度並非以Y值表示。故選項D錯誤。', 19, '[{"is_correct":false,"key":"A","sort_order":1,"text":"以色光混色為基礎，運用光學儀器來設定色彩"},{"is_correct":false,"key":"B","sort_order":2,"text":"以色光三原色為準，設定為三種X、Y、Z的刺激值"},{"is_correct":false,"key":"C","sort_order":3,"text":"XYZ的刺激值，是由RGB體系數值換算而成"},{"is_correct":true,"key":"D","sort_order":4,"text":"由於X至Z階段的色度之彩度為10，所以色彩的彩度以Y值表示"}]'::jsonb),
  ('518651b0-f738-21a6-2444-eba04f474957', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3020', 'chapter', '下列有關色彩命名的方式，何者較不適當？', '鈦白、鈷藍為顏料名稱（固有色名），並非按明度來命名。故選項A較不適當。', 20, '[{"is_correct":true,"key":"A","sort_order":1,"text":"按顏色明度來命名，如鈦白、鈷藍"},{"is_correct":false,"key":"B","sort_order":2,"text":"以原料來命名，如藤黃、赭石"},{"is_correct":false,"key":"C","sort_order":3,"text":"按顏色合成情況來命名，如紅橙、黃綠"},{"is_correct":false,"key":"D","sort_order":4,"text":"以自然物色來命名，如玫瑰紅、橄欖綠"}]'::jsonb),
  ('3d0fc63d-4c84-729d-d4b9-dab5b859bba2', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3021', 'chapter', '若某顏色標示為「Y90＋M100＋C50」的數值，則最接近下列何種色彩？', 'Y90+M100+C50，洋紅偏多且帶黃與青，混合後呈現棕色。故選項D正確。', 21, '[{"is_correct":false,"key":"A","sort_order":1,"text":"淺綠色"},{"is_correct":false,"key":"B","sort_order":2,"text":"青色"},{"is_correct":false,"key":"C","sort_order":3,"text":"青灰色"},{"is_correct":true,"key":"D","sort_order":4,"text":"棕色"}]'::jsonb),
  ('99a947c4-9edb-1212-d4ad-a30288c2ffca', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3022', 'chapter', '若某色彩標示為「Y50＋M50＋C100」的數值，則最接近下列何種色彩？', 'Y50+M50+C100，青色最多，帶有等量黃紅（形成灰），故呈現青灰色。故選項C正確。', 22, '[{"is_correct":false,"key":"A","sort_order":1,"text":"紅灰色"},{"is_correct":false,"key":"B","sort_order":2,"text":"黃灰色"},{"is_correct":true,"key":"C","sort_order":3,"text":"青灰色"},{"is_correct":false,"key":"D","sort_order":4,"text":"紫灰色"}]'::jsonb),
  ('820fcaa2-5239-1df4-fa7b-5151fd2e0733', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3023', 'chapter', '有關「色立體造形」的敘述，下列何者正確？', 'PCCS色立體因各色相最高彩度位置不同，俯視圖為圓形。故選項A正確。', 23, '[{"is_correct":true,"key":"A","sort_order":1,"text":"PCCS色立體之俯視圖為圓形"},{"is_correct":false,"key":"B","sort_order":2,"text":"奧斯華德（Ostwald）色立體之前視圖為圓形"},{"is_correct":false,"key":"C","sort_order":3,"text":"曼塞爾（Munsell）色立體之俯視圖為圓形"},{"is_correct":false,"key":"D","sort_order":4,"text":"NCS色立體之前視圖為圓形"}]'::jsonb),
  ('1e1edf2a-6f1c-d49a-0345-34c3f7b0bdd8', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3024', 'chapter', '某公司計畫推出符合年輕族群偏好的電話手機，若以NCS色彩系統表示時，下列何者較適合年輕族群「鮮明、活潑且引人注目」的色彩意象？', '鮮明活潑應選高彩度，NCS中80-Y50R彩度最高（彩色量80），最適合。故選項B正確。', 24, '[{"is_correct":false,"key":"A","sort_order":1,"text":"3070-R10B"},{"is_correct":true,"key":"B","sort_order":2,"text":"80-Y50R"},{"is_correct":false,"key":"C","sort_order":3,"text":"4060-B50G"},{"is_correct":false,"key":"D","sort_order":4,"text":"4050-B10G"}]'::jsonb),
  ('e7ba99e0-ec94-cef0-7645-874a554048a6', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3025', 'chapter', '有關「曼塞爾（Munsell）色彩體系」的敘述，下列何者正確？', '曼塞爾將純白設為N10，純黑設為N0。故選項B正確。', 25, '[{"is_correct":false,"key":"A","sort_order":1,"text":"曼塞爾色彩體系將理想中的純黑色以「N1」表示"},{"is_correct":true,"key":"B","sort_order":2,"text":"曼塞爾色彩體系將理想中的純白色以「N10」表示"},{"is_correct":false,"key":"C","sort_order":3,"text":"曼塞爾表色系的色彩標示方法為H-V-C"},{"is_correct":false,"key":"D","sort_order":4,"text":"曼塞爾表色系以紅、橙、黃、綠、藍、紫六種色相為基礎"}]'::jsonb),
  ('440c547f-e6c1-7905-aff8-6060ee4e85a4', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3026', 'chapter', '影像處理軟體Photoshop的檢色器中，以H：120°；S：100％；B：100％數值表示的色彩，若對應RGB系統數值，下列何者正確？', 'HSB的120°為綠色，S100 B100為純綠，對應RGB為R0 G255 B0。故選項A正確。', 26, '[{"is_correct":true,"key":"A","sort_order":1,"text":"R：0、G：255、B：0"},{"is_correct":false,"key":"B","sort_order":2,"text":"R：255、G：125、B：0"},{"is_correct":false,"key":"C","sort_order":3,"text":"R：255、G：0、B：0"},{"is_correct":false,"key":"D","sort_order":4,"text":"R：0、G：255、B：255"}]'::jsonb),
  ('797fb48c-8712-10a5-9eee-04bc65a3c633', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3027', 'chapter', '有關各色彩體系色相環的敘述，下列何者正確？', 'PCCS色彩體系是以接近色光與色料三原色的光譜色六色相為基礎。故選項C正確。', 27, '[{"is_correct":false,"key":"A","sort_order":1,"text":"奧斯華德（Ostwald）色彩體系是以赫姆豪茲（Helmholtz）心理五原色學說為基礎"},{"is_correct":false,"key":"B","sort_order":2,"text":"伊登（Itten）色彩體系是以色料三原色（Y、M、C）為基礎"},{"is_correct":true,"key":"C","sort_order":3,"text":"PCCS色彩體系是以接近色光三原色和色料三原色的光譜色六色相為基礎"},{"is_correct":false,"key":"D","sort_order":4,"text":"曼塞爾（Munsell）色彩體系是以赫林（E. Hering）所提的生理四原色學說為基礎"}]'::jsonb),
  ('4d681448-57f3-4d3a-4410-b2338b6d7739', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3028', 'chapter', '以5050-B80G表色法表示之色彩，屬於哪種表色色彩體系？', '5050-B80G符合NCS表色法格式（黑量 彩色量 - 色相）。故選項C正確。', 28, '[{"is_correct":false,"key":"A","sort_order":1,"text":"Munsell"},{"is_correct":false,"key":"B","sort_order":2,"text":"Ostwald"},{"is_correct":true,"key":"C","sort_order":3,"text":"NCS"},{"is_correct":false,"key":"D","sort_order":4,"text":"CIE"}]'::jsonb),
  ('93850b03-85b6-2108-d563-2ded4547d746', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3029', 'chapter', '色票是進行色彩計畫及色彩管理時重要之工具，下列敘述何者正確？', 'PANTONE色票由美國出版，為廣泛使用的印刷油墨色票系統。故選項C正確。', 29, '[{"is_correct":false,"key":"A","sort_order":1,"text":"PCCS色票由大日本顏料及化學公司出版，該公司亦曾出版中國傳統色之色票集"},{"is_correct":false,"key":"B","sort_order":2,"text":"DIC色票以日本色研實用配色體系為依據，是臺灣學生課堂實作最常用的色票"},{"is_correct":true,"key":"C","sort_order":3,"text":"PANTONE色票依據曼塞爾（Munsell）色彩體系而製作，由美國PANTONE公司出版"},{"is_correct":false,"key":"D","sort_order":4,"text":"印刷演色數值色票（又稱印刷色量色票）以紅（Red）、綠（Green）、藍（Blue）、黑（Black）等四個印刷色的百分比值標示色彩"}]'::jsonb),
  ('49aaee96-4b28-ec26-d8ef-43bffd3e82ff', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3030', 'chapter', '有關各色彩體系標示色彩值的方法，下列敘述何者正確？', '國際照明委員會訂定的CIE體系表色法為XYZ。故選項A正確。', 30, '[{"is_correct":true,"key":"A","sort_order":1,"text":"國際照明委員會訂定的CIE體系為XYZ"},{"is_correct":false,"key":"B","sort_order":2,"text":"NCS色彩體系為HV/C"},{"is_correct":false,"key":"C","sort_order":3,"text":"曼塞爾（Munsell）色彩體系是SC-Φ"},{"is_correct":false,"key":"D","sort_order":4,"text":"PCCS日本色研實用配色體系為SVH"}]'::jsonb),
  ('13d7e189-4b6d-5ea9-c42a-90daef4de304', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3031', 'chapter', '關於色彩體系（表色系）中的明度設計，下列敘述何者正確？', '奧斯華德明度分為a， c， e， g， i， l， n， p等8階。故選項B正確。', 31, '[{"is_correct":false,"key":"A","sort_order":1,"text":"NCS色彩體系的無彩色明度值以B標示"},{"is_correct":true,"key":"B","sort_order":2,"text":"奧斯華德（Ostwald）色彩體系的明度分為a、c、e、g、i、l、n、p等8階"},{"is_correct":false,"key":"C","sort_order":3,"text":"曼塞爾（Munsell）色彩體系明度軸的兩個端點，一端為N0白色，另一端為N10黑色"},{"is_correct":false,"key":"D","sort_order":4,"text":"色立體是一種有系統的色彩結構，其明度軸貫穿水平面，通常左端為黑色，向右依序漸變為深灰、中灰、淺灰，最右則為白色"}]'::jsonb),
  ('f9842869-c870-c6a1-4b4e-d956f16bbf4a', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3032', 'chapter', '請參考題圖所示之3D結構圖，研判所標示的色彩屬性（Color Attributes）何者正確？', '在色立體結構中，垂直的甲軸代表明度軸。故選項A正確。', 32, '[{"is_correct":true,"key":"A","sort_order":1,"text":"垂直的甲軸是明度軸"},{"is_correct":false,"key":"B","sort_order":2,"text":"乙（橢圓盤）為同色相面"},{"is_correct":false,"key":"C","sort_order":3,"text":"丙點離甲軸愈遠，彩度愈低"},{"is_correct":false,"key":"D","sort_order":4,"text":"此圖無法用來標示色立體的屬性結構"}]'::jsonb),
  ('86d07388-e357-c1dc-5358-ed71c8b30459', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3033', 'chapter', '關於彩色印刷作業，下列敘述何者不正確？', '印刷演色表標示油墨用量，若C、M、Y均為100％，則呈現黑色而非白色。故選項D不正確。', 33, '[{"is_correct":false,"key":"A","sort_order":1,"text":"印刷界慣用的油墨為色料三原色，再加上黑（Black）等四色"},{"is_correct":false,"key":"B","sort_order":2,"text":"彩色原稿需先分色做出C、M、Y、K四個分色片，它們再過網製出小點構成的網版"},{"is_correct":false,"key":"C","sort_order":3,"text":"網點構成的彩色印刷，係利用並置混合的原理，套印四色而成"},{"is_correct":true,"key":"D","sort_order":4,"text":"演色表標示油墨的用量，若C、M、Y均為100％，而K為0％，則該色為白色"}]'::jsonb),
  ('98536e84-85aa-f8b5-99d5-0724059c8012', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3034', 'chapter', '國際照明委員會於西元1931年正式採用哪一種表色系，作為國際測色標準？', '1931年國際照明委員會正式採用CIE表色系作為國際測色標準。故選項A正確。', 34, '[{"is_correct":true,"key":"A","sort_order":1,"text":"CIE表色系"},{"is_correct":false,"key":"B","sort_order":2,"text":"PCCS表色系"},{"is_correct":false,"key":"C","sort_order":3,"text":"Munsell表色系"},{"is_correct":false,"key":"D","sort_order":4,"text":"Ostwald表色系"}]'::jsonb),
  ('1c7ea34b-9006-5a6b-0819-c79ff0129aa7', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3035', 'chapter', '把色彩的三屬性，有系統地排列組合成一個立體形態的色彩結構，是下列哪一個選項？', '將色彩的三屬性有系統地排列組合成一個立體形態的結構，稱為色立體。故選項C正確。', 35, '[{"is_correct":false,"key":"A","sort_order":1,"text":"短調"},{"is_correct":false,"key":"B","sort_order":2,"text":"CIE表色系"},{"is_correct":true,"key":"C","sort_order":3,"text":"色立體"},{"is_correct":false,"key":"D","sort_order":4,"text":"紅外線"}]'::jsonb),
  ('79f79c50-070c-56e0-b9d1-c7a43ad5ff94', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3036', 'chapter', '對色彩彩度的敘述，下列何者不正確？', '彩度指色彩的飽和度、純度或鮮濁度，不包含明亮度（明度）。故選項A不正確。', 36, '[{"is_correct":true,"key":"A","sort_order":1,"text":"色彩明亮度"},{"is_correct":false,"key":"B","sort_order":2,"text":"Chroma，簡稱C"},{"is_correct":false,"key":"C","sort_order":3,"text":"色彩飽和度"},{"is_correct":false,"key":"D","sort_order":4,"text":"彩色純度"}]'::jsonb),
  ('75a91e97-b0b4-ef86-9f67-0ec9cfbd049b', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3037', 'chapter', '彩色印刷實務中，若標示「M50 Y100」，下列何者最接近印刷演色表上看到的顏色？', 'M50（洋紅）與Y100（黃）混合，黃色比例高，會呈現橙色。故選項B正確。', 37, '[{"is_correct":false,"key":"A","sort_order":1,"text":"綠色"},{"is_correct":true,"key":"B","sort_order":2,"text":"橙色"},{"is_correct":false,"key":"C","sort_order":3,"text":"黃色"},{"is_correct":false,"key":"D","sort_order":4,"text":"紫色"}]'::jsonb),
  ('06112b2b-f800-f037-5f26-d1c8571dfc4e', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3038', 'chapter', 'PCCS表色系中，英文小寫「d」的色調記號是指：', 'PCCS表色系中，英文小寫「d」為dull的簡稱，代表濁（鈍）色調。故選項A正確。', 38, '[{"is_correct":true,"key":"A","sort_order":1,"text":"濁（鈍）色調"},{"is_correct":false,"key":"B","sort_order":2,"text":"暗色調"},{"is_correct":false,"key":"C","sort_order":3,"text":"深色調"},{"is_correct":false,"key":"D","sort_order":4,"text":"暗灰色調"}]'::jsonb),
  ('44cbe8bb-9fd9-2f5a-c142-2fb01056da8d', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3039', 'chapter', '下列何種表色系，不屬於色彩體系中的「顯色系」？', 'CIE表色系透過儀器測量光波，屬於混色系，不屬於依賴色票的顯色系。故選項D正確。', 39, '[{"is_correct":false,"key":"A","sort_order":1,"text":"NCS表色系"},{"is_correct":false,"key":"B","sort_order":2,"text":"曼塞爾（Munsell）表色系"},{"is_correct":false,"key":"C","sort_order":3,"text":"PCCS表色系"},{"is_correct":true,"key":"D","sort_order":4,"text":"CIE表色系"}]'::jsonb),
  ('0a5aa96c-656d-cc10-92cb-cf4203ced7a4', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3040', 'chapter', '某純色若加入黑色，會產生下列何種變化？', '純色加入黑色後，明度會降低，同時純度下降導致彩度變低。故選項B正確。', 40, '[{"is_correct":false,"key":"A","sort_order":1,"text":"明度與彩度都變高"},{"is_correct":true,"key":"B","sort_order":2,"text":"明度與彩度都變低"},{"is_correct":false,"key":"C","sort_order":3,"text":"明度變高、彩度變低"},{"is_correct":false,"key":"D","sort_order":4,"text":"明度變低、彩度變高"}]'::jsonb),
  ('9003d6ae-595f-089c-0e00-75095574024e', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3041', 'chapter', '下列何者全部採用赫林（E. Hering）的四原色學說所建構的色彩體系？', 'CIE Lab、NCS自然色彩體系、奧斯華德色彩體系皆採用赫林四原色學說。故選項A正確。', 41, '[{"is_correct":true,"key":"A","sort_order":1,"text":"CIE Lab體系、自然色彩體系（NCS）、奧斯華德（Ostwald）色彩體系"},{"is_correct":false,"key":"B","sort_order":2,"text":"曼塞爾（Munsell）體系、奧斯華德（Ostwald）色彩體系、自然色彩體系（NCS）"},{"is_correct":false,"key":"C","sort_order":3,"text":"伊登（Itten）表色體系、曼塞爾（Munsell）體系、奧斯華德（Ostwald）色彩體系"},{"is_correct":false,"key":"D","sort_order":4,"text":"奧斯華德（Ostwald）色彩體系、PCCS色彩體系、曼塞爾（Munsell）體系"}]'::jsonb),
  ('49df294b-c14e-0d1f-e44c-4bd4109d93e8', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3042', 'chapter', '右圖為PCCS色彩體系純色2R-4.5-9S之等色相面，下列何者是正確製作該等色相面彩度階段（1S～9S）的方法？', '等色相面彩度階段是以純色加入同明度（N4.5）的無彩色逐階混合製作而成。故選項C正確。', 42, '[{"is_correct":false,"key":"A","sort_order":1,"text":"以純色加入不等份量的N1.5無彩色，逐階製作"},{"is_correct":false,"key":"B","sort_order":2,"text":"以純色加入不等份量的N2.5無彩色，逐階製作"},{"is_correct":true,"key":"C","sort_order":3,"text":"以純色加入不等份量的N4.5無彩色，逐階製作"},{"is_correct":false,"key":"D","sort_order":4,"text":"純色加入不等份量的N9.5無彩色，逐階製作"}]'::jsonb),
  ('1779c583-5c8b-9dbe-7400-3b2e9d274cdb', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3043', 'chapter', '來自六個地區的隊伍參加運動競賽，若大會希望透過隊服的色彩變化以達到區別不同隊伍的目的，最適合的作法為何？', '區別不同隊伍最直觀且有效的方法是採用不同色相，以達到最高辨識度。故選項A正確。', 43, '[{"is_correct":true,"key":"A","sort_order":1,"text":"採用6個不同色相"},{"is_correct":false,"key":"B","sort_order":2,"text":"採用6個不同明度"},{"is_correct":false,"key":"C","sort_order":3,"text":"採用6個不同彩度"},{"is_correct":false,"key":"D","sort_order":4,"text":"採用6個不同灰階"}]'::jsonb),
  ('3e056d98-c953-ff49-0e38-7a913e68019b', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3044', 'chapter', '有關色彩體系中色立體的敘述，下列何者正確？', '曼塞爾明度分為11階（N0-N10），彩度各色相不同，色立體呈不規則樹形。故選項B正確。', 44, '[{"is_correct":false,"key":"A","sort_order":1,"text":"奧斯華德（Ostwald）表色系的明度分成9個階段，由白到黑的順序為9.5到1.0；彩度分成9個階段，色立體呈現蛋形"},{"is_correct":true,"key":"B","sort_order":2,"text":"曼塞爾（Munsell）表色系的明度分成11個階段，由白到黑的順序為N10到N0；彩度分成14個階段，色立體呈現不規則、類似樹形"},{"is_correct":false,"key":"C","sort_order":3,"text":"PCCS表色系的明度分成8個階段，由白到黑的順序為a到p，再以明度階段為中心軸形成正三角形，色立體呈現菱形珠子的形狀"},{"is_correct":false,"key":"D","sort_order":4,"text":"NCS表色系的色立體以藍－綠、紅－黃、黑－白等基本色為三個座標軸，呈現不對稱的斜橢圓形"}]'::jsonb),
  ('16eeeeee-0780-48bf-90cc-f46318fe7257', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3045', 'chapter', '自然色彩體系（NCS）色彩的表色法SC－Φ依序為：', 'NCS表色法SC-Φ依序代表：黑量（S）、彩色量（C）、色相（Φ）。故選項C正確。', 45, '[{"is_correct":false,"key":"A","sort_order":1,"text":"彩色量－色相－黑色量"},{"is_correct":false,"key":"B","sort_order":2,"text":"色相－彩色量－黑色量"},{"is_correct":true,"key":"C","sort_order":3,"text":"黑色量－彩色量－色相"},{"is_correct":false,"key":"D","sort_order":4,"text":"黑色量－色相－彩色量"}]'::jsonb),
  ('7d0c04ed-f315-1240-91ec-9c2e5fcbf850', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3046', 'chapter', '有關色彩三屬性的敘述，下列何者正確？', '黃色屬於高明度色彩，紫色屬於低明度色彩。辨識彩度不宜用灰度處理。故選項D正確。', 46, '[{"is_correct":false,"key":"A","sort_order":1,"text":"中國水墨畫「墨分五色」指的是彩度變化"},{"is_correct":false,"key":"B","sort_order":2,"text":"鮮綠、紫紅是基本色名"},{"is_correct":false,"key":"C","sort_order":3,"text":"要辨識彩度高低時，可用黑白攝影或影像軟體灰度處理"},{"is_correct":true,"key":"D","sort_order":4,"text":"黃色屬於高明度色彩，紫色屬於低明度色彩"}]'::jsonb),
  ('752f5759-11ca-0dc2-fd35-35f16d7393a4', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3047', 'chapter', '有關色票的敘述，下列何者正確？', '運用色票進行精確的比色工作，必須於標準光源條件下進行以避免色偏。故選項C正確。', 47, '[{"is_correct":false,"key":"A","sort_order":1,"text":"依據瑞典工業規格出版的貝頓標準色票，簡稱PMS"},{"is_correct":false,"key":"B","sort_order":2,"text":"DIC色票是以德國DIN表色系發表"},{"is_correct":true,"key":"C","sort_order":3,"text":"運用色票進行比色工作，應於標準光源條件下進行"},{"is_correct":false,"key":"D","sort_order":4,"text":"紙本的PANTONE色票有U、C之分，其中U代表Unique特殊色"}]'::jsonb),
  ('80ef13ba-b898-4880-1ada-cb1ad04c5108', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3048', 'chapter', '下列哪兩種色票是依據曼塞爾（Munsell）和奧斯華德（Ostwald）色彩體系的優點所完成的？', 'PCCS色票結合了曼塞爾（等知覺色階）與奧斯華德（色調概念）的優點。故選項C正確。', 48, '[{"is_correct":false,"key":"A","sort_order":1,"text":"FOCOLTONE色票、DIC色票"},{"is_correct":false,"key":"B","sort_order":2,"text":"PANTONE色票、NCS色票"},{"is_correct":true,"key":"C","sort_order":3,"text":"PCCS色票、NCS色票"},{"is_correct":false,"key":"D","sort_order":4,"text":"PCCS色票、TOYO色票"}]'::jsonb),
  ('6f208c89-1d36-bf25-0923-bf32260a09f6', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3049', 'chapter', 'PCCS表色系中，8Y-8.5-8S和20V-3.5-9S兩色相比，前者比後者：', '8Y-8.5-8S（明度8.5， 彩度8S）與20V-3.5-9S（明度3.5， 彩度9S）相比，前者明度較高，彩度較低。故選項D正確。', 49, '[{"is_correct":false,"key":"A","sort_order":1,"text":"明度低，彩度高"},{"is_correct":false,"key":"B","sort_order":2,"text":"明度高，彩度高"},{"is_correct":false,"key":"C","sort_order":3,"text":"明度低，彩度低"},{"is_correct":true,"key":"D","sort_order":4,"text":"明度高，彩度低"}]'::jsonb),
  ('b221285e-9aa9-01ca-2093-77f6dcab5446', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3050', 'chapter', '有關CIE色度圖的敘述，下列何者不正確？', '1931 XYZ色度圖的外觀呈現馬蹄形，而非橢圓形。故選項C不正確。', 50, '[{"is_correct":false,"key":"A","sort_order":1,"text":"表示人類眼睛可視的所有色彩範圍"},{"is_correct":false,"key":"B","sort_order":2,"text":"可以用Y、x、y分別表示色光反射率、X座標及Y座標的數值"},{"is_correct":true,"key":"C","sort_order":3,"text":"1931 XYZ色度圖是橢圓形狀"},{"is_correct":false,"key":"D","sort_order":4,"text":"利用色度圖可以標示出任何色彩材料或工具設備可以顯示的色彩最大範圍"}]'::jsonb),
  ('f8857a78-1fa4-f816-e85d-bac6cad8fbf3', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3051', 'chapter', '90年代之後，數位色彩孕育而生，視覺設計師、產品設計師、建築師等開始利用電腦進行創作，關於數位色彩的敘述，下列何者不正確？', 'RGB模式轉換為CMYK模式是透過色彩描述檔（ICC Profile），不需FOCOLTONE作仲介。故選項B不正確。', 51, '[{"is_correct":false,"key":"A","sort_order":1,"text":"數位圖像是由許多小色點構成，這些色點稱為「像素」（Pixel）"},{"is_correct":true,"key":"B","sort_order":2,"text":"RGB模式要轉換CMYK模式，需要以FOCOLTONE作為色彩轉換的仲介"},{"is_correct":false,"key":"C","sort_order":3,"text":"Photoshop、Illustrator等軟體中，可以選擇使用RGB模式或CMYK模式的色樣本"},{"is_correct":false,"key":"D","sort_order":4,"text":"數位色彩是建立在RGB的色彩系統，由RGB三色並置混色而成"}]'::jsonb),
  ('a79f7793-02cf-a6ba-236c-fbdb01ada091', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3052', 'chapter', '下列何種色彩不是曼塞爾（Munsell）色彩體系五原色的補色？', '曼塞爾五原色為紅黃綠藍紫。黃橙並非五原色，故不是五原色的補色。故選項D正確。', 52, '[{"is_correct":false,"key":"A","sort_order":1,"text":"藍綠"},{"is_correct":false,"key":"B","sort_order":2,"text":"黃綠"},{"is_correct":false,"key":"C","sort_order":3,"text":"紅紫"},{"is_correct":true,"key":"D","sort_order":4,"text":"黃橙"}]'::jsonb),
  ('603d607e-d449-29b5-f8ed-ec7ca7675c1e', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3053', 'chapter', '關於色料與色光的敘述，下列何者正確？', '色料相互混合屬於減法混色，次數愈多，明度與彩度皆會減低。故選項B正確。', 53, '[{"is_correct":false,"key":"A","sort_order":1,"text":"色光相互混合次數愈多，明度則減低"},{"is_correct":true,"key":"B","sort_order":2,"text":"色料相互混合次數愈多，彩度則減低"},{"is_correct":false,"key":"C","sort_order":3,"text":"伊登（Itten）的色相環是依據色光三原色的原理而成"},{"is_correct":false,"key":"D","sort_order":4,"text":"旋轉混色是屬於色料混合的特性"}]'::jsonb),
  ('a8cee483-bdfe-bd1f-ed27-ba74d1433da1', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3054', 'chapter', '下列何種組合的色票都是依據曼塞爾色彩體系製作？', 'PANTONE色票與ISCC-NBS色名法皆與曼塞爾色彩體系有密切關聯。故選項D正確。', 54, '[{"is_correct":false,"key":"A","sort_order":1,"text":"DIC色票、DIN色票"},{"is_correct":false,"key":"B","sort_order":2,"text":"Colorcurve色票、TRUMATCH色票"},{"is_correct":false,"key":"C","sort_order":3,"text":"PCCS色票、中華色彩研究所色票"},{"is_correct":true,"key":"D","sort_order":4,"text":"PANTONE色票、ISCC-NBS色票"}]'::jsonb),
  ('f8daee43-829b-0f2e-019e-58b4d088d41d', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3055', 'chapter', '有關CIE色彩體系的敘述，下列何者正確？', 'CIE色彩體系精確度高，多運用於色彩管理、顏料和紡織品測色比對工作。故選項D正確。', 55, '[{"is_correct":false,"key":"A","sort_order":1,"text":"用色樣及色票來測色，是最精確的色彩表示"},{"is_correct":false,"key":"B","sort_order":2,"text":"曾被NCS色彩體系作為修正及測定色彩的標準"},{"is_correct":false,"key":"C","sort_order":3,"text":"CIE L*a*b*是以楊格（Young）和赫姆豪茲（Helmholtz）的色光三原色為基礎"},{"is_correct":true,"key":"D","sort_order":4,"text":"多運用於色彩管理、顏料和紡織品測色比對的工作上"}]'::jsonb),
  ('548ab406-6b08-0da4-9932-e161f22357ee', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3056', 'chapter', '德國生理學家赫林（Hering）所提出的生理四原色，被應用於下列何種色彩表色系中？', '德國生理學家赫林提出的生理四原色（紅綠黃藍），被應用於奧斯華德表色系。故選項A正確。', 56, '[{"is_correct":true,"key":"A","sort_order":1,"text":"奧斯華德（Ostwald）表色系"},{"is_correct":false,"key":"B","sort_order":2,"text":"曼塞爾（Munsell）表色系"},{"is_correct":false,"key":"C","sort_order":3,"text":"PMS配色系統"},{"is_correct":false,"key":"D","sort_order":4,"text":"伊登（Itten）表色系"}]'::jsonb),
  ('f6f080be-0f54-51c0-9e38-18af412491b5', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3057', 'chapter', '有關CIE的敘述，下列何者不正確？', 'CIEXYZ中，Y代表明度與反射率，Z代表藍色刺激值，並非明度。故選項B不正確。', 57, '[{"is_correct":false,"key":"A","sort_order":1,"text":"被廣泛運用於色彩管理、色彩複製與校正領域"},{"is_correct":true,"key":"B","sort_order":2,"text":"CIEXYZ中的Y是指明度"},{"is_correct":false,"key":"C","sort_order":3,"text":"CIE1976Lab的b表示藍色到黃色的值，數值介於－100至100間"},{"is_correct":false,"key":"D","sort_order":4,"text":"適用於色彩工程、色彩管理等精密工作，有色彩文法之稱"}]'::jsonb),
  ('01110652-88d7-1fd6-bb9d-a8683a81befd', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3058', 'chapter', '有關色名的表示方法，下列何者不屬於固有色名的範疇？', '以色調名稱（如粉紅、暗紅）來表示色彩屬於系統色名，不屬於固有色名。故選項A正確。', 58, '[{"is_correct":true,"key":"A","sort_order":1,"text":"以色調名稱的色彩表示法"},{"is_correct":false,"key":"B","sort_order":2,"text":"以動植物為名的色彩表示法"},{"is_correct":false,"key":"C","sort_order":3,"text":"以礦物色名的色彩表示法"},{"is_correct":false,"key":"D","sort_order":4,"text":"以國家地域為名的色彩表示法"}]'::jsonb),
  ('6c4b6b32-6831-28a3-ed39-d42f3b527e00', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3059', 'chapter', '有關彩通（Pantone）標準色票的敘述，下列何者正確？', '文化部等單位曾以PANTONE 219C色票來標示「臺灣紅」。故選項C正確。', 59, '[{"is_correct":false,"key":"A","sort_order":1,"text":"是依據伊登色彩體系所製作的印刷油墨色票"},{"is_correct":false,"key":"B","sort_order":2,"text":"色票色號以字母U來標示產地來源為美國"},{"is_correct":true,"key":"C","sort_order":3,"text":"文化部等單位曾以上述色票219C表示「臺灣紅」"},{"is_correct":false,"key":"D","sort_order":4,"text":"色票種類包含環保有機顏料與化學顏料二種"}]'::jsonb),
  ('3ce65351-5e9b-ec1a-772a-5203e144d15d', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3060', 'chapter', '進行網頁設計時，下列何種色彩模式較適用且常見於網頁的影像？', '進行網頁設計時，最適用且常見於螢幕顯示的色彩模式為sRGB。故選項A正確。', 60, '[{"is_correct":true,"key":"A","sort_order":1,"text":"sRGB"},{"is_correct":false,"key":"B","sort_order":2,"text":"HSB"},{"is_correct":false,"key":"C","sort_order":3,"text":"CMYK"},{"is_correct":false,"key":"D","sort_order":4,"text":"Lab"}]'::jsonb),
  ('8b2141f5-058e-c24f-96f3-26311acca50e', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3061', 'chapter', 'NCS自然色彩體系的色立體造形，最接近下列何種型態？', 'NCS自然色彩體系的色立體造形，最接近對稱的複圓錐體。故選項B正確。', 61, '[{"is_correct":false,"key":"A","sort_order":1,"text":"馬蹄形"},{"is_correct":true,"key":"B","sort_order":2,"text":"複圓錐體"},{"is_correct":false,"key":"C","sort_order":3,"text":"圓球體"},{"is_correct":false,"key":"D","sort_order":4,"text":"斜橢圓形"}]'::jsonb),
  ('41247f08-733a-baac-1bd5-1095a2267ec8', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3062', 'chapter', 'NCS色彩體系中S 2060-Y70R色彩的敘述，下列何者正確？', 'S 2060-Y70R中，黑量20，彩色量60，故白色量為100-20-60=20。故選項B正確。', 62, '[{"is_correct":false,"key":"A","sort_order":1,"text":"該色彩的色彩量為40"},{"is_correct":true,"key":"B","sort_order":2,"text":"該色彩的白色量為20"},{"is_correct":false,"key":"C","sort_order":3,"text":"與R30B形成對比色"},{"is_correct":false,"key":"D","sort_order":4,"text":"紅色含量近似R70B"}]'::jsonb),
  ('207594de-5fad-79f9-432f-d55f4f0d5a09', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3063', 'chapter', '有關色彩①～④的明度由高至低排列，下列何者正確？ ① R225：G225：B225 ② C20：M10：Y25：K80 ③ #808080 ④ L*=100，a*=0，b*=0', '④L*=100最亮；①RGB225次之；③灰階128；②K80最暗。明度由高至低為④①③②。故選項D正確。', 63, '[{"is_correct":false,"key":"A","sort_order":1,"text":"③→④→①→②"},{"is_correct":false,"key":"B","sort_order":2,"text":"④→③→①→②"},{"is_correct":false,"key":"C","sort_order":3,"text":"④→①→②→③"},{"is_correct":true,"key":"D","sort_order":4,"text":"④→①→③→②"}]'::jsonb),
  ('aad25f7a-ffe5-c431-8d90-1e9b29a969e6', 'f013d0e5-93b6-f63e-9e76-b55e7aaac397', 'CR3064', 'chapter', '依據PCCS表色系統，甲色標示為「5O-4.5-9S」，乙色標示為「5O-3.5-2S」，下列敘述何者正確？', '甲色明度為4.5，乙色明度為3.5，故甲色的明度比乙色高。故選項B正確。', 64, '[{"is_correct":false,"key":"A","sort_order":1,"text":"甲乙兩色皆為淺色調"},{"is_correct":true,"key":"B","sort_order":2,"text":"甲色的明度比乙色高"},{"is_correct":false,"key":"C","sort_order":3,"text":"甲乙兩色的色相不同"},{"is_correct":false,"key":"D","sort_order":4,"text":"甲色的彩度比乙色低"}]'::jsonb)
    )
    select 1
    from incoming
    join public.questions existing
      on existing.id = incoming.id::uuid or existing.stable_code = incoming.stable_code
    where existing.status <> 'published'
      or row(existing.subtopic_id, existing.stable_code, existing.bank_kind, existing.prompt, existing.explanation, existing.sort_order)
        is distinct from row(incoming.subtopic_id::uuid, incoming.stable_code, incoming.bank_kind, incoming.prompt, incoming.explanation, incoming.sort_order)
      or coalesce((
        select jsonb_agg(jsonb_build_object('key', option.option_key, 'text', option.option_text, 'is_correct', option.is_correct, 'sort_order', option.sort_order) order by option.sort_order)
        from public.question_options option where option.question_id = existing.id
      ), '[]'::jsonb) is distinct from incoming.options
  ) then
    raise exception using errcode = 'P0001', message = 'CONTENT_VERSION_REQUIRED';
  end if;
end
